INSERT INTO transfer_targets VALUES(10,'AVL','2026-summer','Modou Kéba Cissé','시세',1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED','00200001420237413X9814X84',60.89999999999999858,31.19999999999999929,6,6.769999999999999574,'cb_defender','Balanced','cb_bpd','Aggressive',0.8559999999999999832,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','https://readastonvilla.com/2026/05/14/modou-keba-cisse-the-future-aston-villa-player-who-is-shining-in-austria/ ; SofaScore API player 1944705 (2026-07-02)','CONFIRMED signing; measured from LASK (league-strength caveat). / 2026-07-15: 공식 완료 확인 — CONFIRMED 유지.','시세',NULL);
INSERT INTO transfer_targets VALUES(13,'AVL','2026-summer','Alysson','알리송',1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED','001640014X000380003600011',83.20000000000000284,59.70000000000000284,6,6.75,'wm_winger','Balanced','wm_winger','Balanced',0.8349999999999999645,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','https://www.fotmob.com/teams/10252/transfers/aston-villa ; SofaScore API player 1631879 (2026-07-02)','OWNED; measured mixes Grêmio+Villa minutes (sample caveat). / 🔄 **[2026-07-31 obs#100 — 커널 교체 후 재산출]** 옛 기준(obs#93·#94 이전) 잔존값을 정정했다. 브라우저에서 툴 `placedMap`·`cmpCos`를 직접 호출해 산출(컨텍스트 노트 2), 회귀 게이트 하지무사 .821 재현 확인. 알리송 RM(x=85): .847 (wm_winger/Attack) → **wm_winger/Balanced 0.835**.',NULL,NULL);
INSERT INTO transfer_targets VALUES(18,'AVL','2026-summer','Anis Hadj Moussa','하지 무사',1218066,'Feyenoord','RW','RM','DEAD (STALE — 빌라 특정 보도 2026-07-03 이후 27일 무소식)','312691114X000140002400001',76.90000000000000569,69.29999999999999716,6,7.549999999999999823,'wm_winger','Attack','wm_winger','Attack',0.8209999999999999521,'ADVANCE TALKS (Villa vs Newcastle); player prioritising a PL move for 26/27, Feyenoord ask ~€35m. Measured: high-and-wide right winger (76.9,69.3), Inside Forward/Attack fit 0.92 — the HIGHEST RM-slot fit sampled (Bowen 0.88) AND the highest avg rating of all targets (7.55). Eredivisie level caveat. [2026-07-03 watch: talks well underway with both Villa & Newcastle, expected to accelerate; Newcastle edge — Villa CL squad-registration restriction (UEFA fine) may hamper. Feyenoord ~€35m. Grade unchanged.] [2026-07-09 watch: TransferFeed/Yahoo — 빌라·뉴캐슬이 "most advanced in discussions" 공식 표현으로 보도, 선수 본인도 PL 선호 재확인. MEDIUM-HIGH에서 HIGH 상향.] [2026-07-15 재확인] Sacha Tavolieri(2티어급): "advanced talks" 보도 재확인, 대리인이 빌라·뉴캐슬 지목. 페예노르트 €35m 고수. [2026-07-15 3축+스탯 — 교정 winger/Attack→insidefwd/Attack] 6경기 스탯: xG .42·xA .46·kp 3.2·드리블 2.0·3골(평점 7.50 후보군 1위). 기능=득점+창조 양방 엘리트 = 컷인형 인사이드 포워드. 현커널 움직임도 insidefwd/Attack .923 최상 — 2축 일치로 교정. [2026-07-19 재검증] advanced talks 근거였던 Sky Sport Switzerland(Tavolieri)는 영국 Sky Sports 공식(tier-1)과 별개 매체로 재분류 — HIGH 유지 근거 약화. 선덜랜드 신규 문의·첼시 모니터링으로 경쟁 확대. [2026-07-27 21시 최신화] Sacha Tavolieri(Sky Sport Switzerland, 신뢰도 높은 이적 전문기자) — 빌라·뉴캐슬 "advanced talks". 페예노르트 €35m 요구, 선수 측(에이전트 Dahmane)은 PL행 확정적 의사 표명, 사우디 오퍼 거절. 뉴캐슬과 양자 경쟁 구도 유지. [2026-07-28 FC26 통합 확인] 실측 0.923 + 숙련 w_insidefwd+(동계열 W그룹) + #드리블러/#곡예사 — 처방 확정. [2026-07-29 14시 재확인 — 유지] 빌라·뉴캐슬이 최선두 협상(TransferFeed), Feyenoord €35m 최소가·2030 계약. Sky: 선수 잉글랜드행 희망(사우디 관심 불구). 대리인 "이번 여름 이탈 예상". [2026-07-29 우측 브리프 정합 검증] 디아비 23/24 실측 템플릿 대비 코사인 .835, RM 커널 insidefwd/Attack .923, 침투 서명 = 전방 2행 0.76(전 후보 최고)·자기진영 2행 0.14 → Tanswell 브리프("뒷공간 반복 침투 빠른 우측 윙어") 정합 1순위. 평점 7.55도 전 타깃 최고. 캐비앗: 에레디비시 레벨. 배치 제약 — B1(해방 우측)에서 Attack 가용, A(가르나초 해방)에서는 좌우 동시 해방 금지(obs#27)로 Support 강제. [경쟁구도 2026-07-30] 대등 — 뉴캐슬이 동일 출처·동일 단계(Tavolieri 6/30, 우열 불명)이고 스포르팅이 7/23 트린캉 대체 1순위로 신규 참전(Santi Aouna, 본 건 최신 보도). Al Ahli는 €30m 정식 오퍼(유일한 정식 입찰)를 페예노르트가 거절, 선더랜드는 접촉 단계. 선수 측은 에이전트 발언으로 PL 지향·사우디 거부 명시 → 사우디·포르투갈 감점, 빌라·뉴캐슬 공통 이점. 페예노르트 호가 €35m→€40m 상승, 계약 2030. **빌라 특정 보도는 7/3이 마지막(27일 경과) = STALE 판정 대상.** 날짜함정: "재계약으로 이적설 종료" 기사는 2025년 여름 건.','https://thehardtackle.com/transfer-news/2026/06/30/aston-villa-newcastle-united-advance-talks-to-sign-anis-hadj-moussa/ ; SofaScore API player 1218066 (2026-07-02); Sacha Tavolieri(Sky Sport Switzerland); TeamTalk; TheHardTackle; Football Insider','MEDIUM-HIGH 유지 — 신뢰도 높은 기자의 협상 진전 보도, 단 빌라 단독이 아닌 뉴캐슬과 경쟁 중이라 HIGH 미달. / [2026-07-30 STALE] §4-3 적용(14일 초과). 실측(map25·insidefwd/Attack .923)은 보존 — 새 보도 확인 시 등급 복원만으로 툴에 재노출. ⚠️ C(우측 침투) 프리셋의 RM 처방 인선이 이 행이므로, 숨김 상태에서 해당 슬롯은 툴에서 경고 표시된다(대안: 카타모 .915 미등재/알리송 .847 보유). / 🔄 **[2026-07-31 obs#100 — 커널 교체 후 재산출]** 옛 기준(obs#93·#94 이전) 잔존값을 정정했다. 브라우저에서 툴 `placedMap`·`cmpCos`를 직접 호출해 산출(컨텍스트 노트 2), 회귀 게이트 하지무사 .821 재현 확인. 하지무사 RM(x=85): .589 (opt_role이 wm_insidefwd로 남아 행 내부 불일치) → **wm_winger/Attack 0.821**.','하지무사','2026-07-03');
INSERT INTO transfer_targets VALUES(30,'AVL','2026-summer','Tammy Abraham','타미 아브라함',610766,'Aston Villa','ST','ST','OWNED','01855255648X8415422010200',47.39999999999999858,59.0,4,6.849999999999999645,'st_target','Attack','st_false9','Attack',0.5210000000000000186,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','https://www.avfc.co.uk/news/2026/january/27/signing-aston-villa-confirm-tammy-abraham-signing/ ; SofaScore API player 610766 (2026-07-03)','OWNED — 이적 루머 아님(2026-01 합류확정 보유선수). 측정 신뢰 MEDIUM(표본 4경기·전부 교체출전·맥락 편향, 45분+ 6경기 미달).',NULL,NULL);
INSERT INTO transfer_targets VALUES(75,'AVL','2026-summer','Pervis Estupiñán','에스투피냔',805465,'AC Milan','LB','LB','DEAD (강등 — 1티어 3곳 무산 방향: 아모림 veto 확정 + 빌라 루헤리 선회, 현재 긍정 보도 0건)','21000X3100610007200032100',16.10000000000000143,49.10000000000000142,6,6.870000000000000106,'fb_att_wb','Support','fb_att_wb','Support',0.945999999999999953,'좌측면 전 깊이 커버 공격형 레프트백. 실측 6경기(세리에A, 322pt) 중심 tool(16,49). 커널 fit fb_att_wb/Support 0.946 (2위 fb_inverted/Build-Up 0.89). 밀란 아모림 구상 외, 호가 ~€14m. [2026-07-14 야간 재확인] Romano: "AVFC 좌측백 3인 숏리스트 중 상위, 딜 진행중, 협상 계속"(YouTube) — 단 조건 미확정, 데포르티보 라코루냐 경쟁 참전. 디뉴 대체가 아니라 마첸 백업/뎁스 역할로 영입(주전 보장 아님). [2026-07-15 재확인] Matteo Moretto(로마노 채널, 준1티어급): "협상 공식 개시" 확인 — 밀란-빌라 간 클럽 대 클럽 협상 단계 진입. 이적료 격차(€18-20m vs €10-12m)만 남음. 협상 단계 확인으로 HIGH 상향. [2026-07-15 3축+스탯 — 유지] 6경기: 패스 89%·태클 1.3·kp .8 — 견실 전진 LB. att_wb/Support 유지(마첸 07-15 교정 처방과 동일 — 경쟁 구도 명확). [2026-07-17 재확인] Romano(1티어): 개인조건 합의 완료. 클럽간 협상 advanced("non-stop contacts" — Longo), 이적료 격차 €12m vs €18-20m에서 Gazzetta €15m 절충설. 완료 임박 국면. [2026-07-18 재확인] 클럽간 최종 협상 단계 — 밀란 €18-20m vs 빌라 €10-12m에서 €15m 절충 근접(Gazzetta), "다음 주 초 이전 타결" 양측 낙관. 결정적 미팅 수일 내. [2026-07-19 재검증 강화] Romano(1티어, 7/16-17): 빌라가 에스투피냔과 개인조건 합의, 선수도 이적 희망, AC밀란과 이적료 협상 계속. 텔레그래프(2티어)도 advanced 확인. 이적료 격차만 남음(18-20m 밀란 요구 vs 10-13m대 빌라). [2026-07-27 상태변화] 정체 심화 → MEDIUM-HIGH 하향. Amorim이 밀란 프리시즌 호주 투어까지 에스투피냔을 직접 평가하겠다며 매각 승인 보류(Tuttosport/Football Italia), 일부 보도는 완전 차단 가능성 시사. 선수는 개인조건 합의·PL 복귀 희망 유지, 이적료 격차 €15-16m 절충설(Gazzetta). 반론: Pellegatti — "감속설은 카르디날레의 몸값 인상용 전술, 협상 계속·타결 임박". 개인합의는 유지되나 클럽 승인 리스크로 HIGH 요건(완료 임박) 미충족. [2026-07-27 21시 최신화] 상충 지속: TheHardTackle(Calciomercato 경유)는 "아모림이 매각 차단" 재확인 보도, 반면 밀란 기자 Antonio Vitello는 "글래스고 이동 명단에 없음"을 근거로 이적 임박 가능성 시사. 로마노·벤 제이콥스(1티어)의 기존 "개인조건 합의·advanced talks" 보도는 유효. [2026-07-28 FC26 통합 확인] 실측 0.946 압도 — 유지. 캐비앗: FC26 숙련은 fb_wingback+(윙백)·wm_winger+, att_wb 숙련 마커는 없음. [2026-07-29 14시 재확인 — 유지] 아모림(밀란 신임감독)이 이적 일시 블록(7/25, Accomando) — 개인합의(2030년까지) 완료·클럽간 ~£13m 근접 상태에서 보류. 셀틱전 스쿼드 제외는 이적 상황 연관 보도. 밀란 최종 판단 대기. [경쟁구도 2026-07-30] 빌라 압도적 우위 — 개인합의(2030년까지 계약 수락)를 가진 유일한 클럽. 유일 경쟁 언급인 데포르티보 라코루냐는 원출처가 무명 스페인 매체(3티어)에 승격팀 자금 근거 없음. 선수도 PL 복귀·에메리(비야레알) 선호 명확. 즉 감점 요인은 경쟁이 아니라 밀란의 출국 블록 하나뿐 → 밀란이 대체 LB(마즈라위 등)를 확보하면 즉시 HIGH 승격 조건 충족. [2026-08-03/04 재확인 — 등급 유지] 아모림이 밀란 프리시즌 호주 투어까지 트레이닝 직접 평가를 이유로 매각 보류 지속(07-25~ 상태 연장). Romano 채널/Moretto(1티어급) 및 The Athletic("이적료는 문제 아님") 재확인 — 개인합의 유효, 클럽 승인만 대기. 신규 악화 신호 없음. [2026-08-04 21시 — 등급 유지, 리스크 상향] Marca/Moretto: 빌라가 ''더 기다리지 않고'' 루헤리(아틀레티코)로 선회해 즉시 영입 시도. 밀란 승인 보류가 계속되는 동안 같은 LB 슬롯의 대체 후보가 오퍼 단계까지 갔다 → 이 건은 이제 슬롯 경쟁에서 밀리는 위치다. 다만 1~2티어의 ''빌라 철수'' 보도는 없고 개인합의(2030년까지)·The Athletic ''이적료는 문제 아님''(08-03)이 유효해 하향 요건 미충족 → MEDIUM-HIGH 유지. ⚠️ 루헤리 딜이 성사되면 이 행은 즉시 DEAD(슬롯 소멸) 전환 대상이다. [2026-08-05 재확인 — 등급 유지] Get Italian Football News/OneFootball 등이 08-04 상황(아모림 매각 보류 지속)을 재서술한 것으로, 정확한 신규 발행일 확인 실패 — 08-04 21시 기록 이후 실질 변화 없음. [2026-08-05 심층 — MEDIUM-HIGH → DEAD 강등] ⚠️ 먼저 자기수정: 08-04 및 08-05 오전 기록이 하향 미충족 근거로 인용한 The Athletic "이적료는 문제 아님(Terms not an issue)"은 2026-08-03이 아니라 **2026-07-21 발행분**이다(milanreports.com/2026/07/21/ 슬러그로 확정, sempremilan 07-21 14:00 동일). 우리가 §2-0 발행일 함정에 걸려 15일 전 기사를 최신 긍정 근거로 승계했다. 정정하면 그림이 뒤집힌다 — **1티어 긍정 보도는 07-21이 마지막이고, 08-03~04 1티어 보도는 전부 부정 방향이다.** 강등 근거: ⑴ Gazzetta dello Sport(1티어) 08-04 — 딜이 "falling through", "not optimistic", 아모림이 직접 차단 결정, 에스투피냔은 "스쿼드의 일부·다음 시즌 가치를 더할 선수"로 분류. ⑵ Moretto(1티어) 08-03 아모림 veto 확정 보도 → 08-04 루헤리 딜이 에스투피냔 이적을 "영구히 막을 수 있다", 빌라가 "지쳐서(fed up)" 선회. 07-24에 "if가 아니라 when의 문제"라고 했던 바로 그 기자가 10일 만에 정반대로 선회한 것이라, 독립 반증보다 무겁다. ⑶ Marca(1티어) 08-04 — 딜이 "식었다(gone cold)", 에메리 관심이 루헤리로 이동. ⑷ 결정적 구조: 밀란 측 아모림 veto와 빌라 측 타깃 전환이 **동시에** 성립한다(양방향 차단). 한쪽만 풀려도 부활하지 않는다. ⑸ 말이 아니라 자금 배분 행동 — €15-16m 협상 중이던 빌라가 더 비싼 €25m 루헤리에 실제 오퍼를 제출했다. 같은 슬롯·같은 예산이라 병행은 실질 불가. ⑹ 선수는 밀란 호주 투어 33인 명단 포함·훈련 정상 참가·다음 친선전 출전 예정 — 이적 임박 선수의 행동 패턴이 아니다. [기각] Pellegatti "카르디날레 몸값 인상용 전술" 가설은 검증 가능한 예측(빌라가 값을 올려 타결)을 낳았으나 실제로는 빌라가 더 비싼 타인에게 갔고 감속 주체도 구단주가 아니라 감독이었다 → 반증 완료. Pellegatti는 밀란 친구단 논평가로 1티어 취재원도 아니다. [사실관계 정정] 07-25 셀틱 친선전 결장을 이적 신호로 읽었던 기존 해석은 오류다 — 실제 사유는 월드컵 휴가 후 늦은 복귀(전날 밀라넬로 복귀)이고 Nkunku 등 12명이 함께 결장했으며 매체가 "부상·이적과 무관"이라 명시했다. [행 보존 이유] §4-3 논리 적용 — map25/fit_sim(.946)·실측 6경기 표본을 잃지 않기 위해 삭제하지 않고 DEAD로 둔다(툴의 injectTransferCandidates가 /^DEAD/i를 건너뛰므로 히트맵·SQUAD_SLOTS·XI_POOL에서는 사라진다). DB 선례(로우·은디아예·사라·반스·레앙)와 동일 처리. [부활 트리거 — 둘 다 충족 시에만 재승격 검토] ① 루헤리 딜 붕괴(선수 거부 또는 아틀레티코 거부) AND ② 아모림 veto 철회. ②의 관찰 가능한 대리지표: 08-05 인테르전(퍼스)·08-08 첼시전(자카르타) 친선 결장, 또는 밀란의 마즈라위 등 대체 윙백 영입 확정. 선발 출전이 확인되면 DEAD 확정.','Moretto via SempreMilan https://sempremilan.com/moretto-aston-villa-enquire-milan-estupinan ; SofaScore player/805465 (6 Serie A ~2026-05-10) ; milanreports 7/21·7/23 (Athletic·Tuttosport 경유, 재검증 07-26) ; [07-27] Yahoo/Football Italia "Amorim asks Milan to hold off on Estupinan deal", milanreports 7/21·7/23; TheHardTackle(Calciomercato); Antonio Vitello(밀란 전담); Fabrizio Romano; Ben Jacobs; Sports Mole ; [08-05 심층] Gazzetta dello Sport(1티어) 2026-08-04 via https://www.getfootballnewsitaly.com/2026/milans-pervis-estupinan-ruben-amorim-blocks-aston-villa-transfer/ ; Moretto(1티어) 2026-08-04 https://sempremilan.com/aston-villa-progress-ruggeri-deal-milan-estupinan-fade ; Moretto/Romano 2026-08-03 https://milanreports.com/2026/08/03/amorim-vetoes-estupinan-exit-whats-next-for-the-ecuadorian-full-back/ ; The Athletic(Tanswell) **2026-07-21**(발행일 정정) https://milanreports.com/2026/07/21/aston-villa-milan-left-back-estupinan/ ; Moretto 07-24 https://sempremilan.com/small-details-left-estupinan-exit-amorim-decision ; 부상이력 https://za.soccerway.com/player/estupinan-pervis/OIhsN1nG/injury-history','MEDIUM-HIGH 유지 — 클럽 차단설과 이적 임박 신호가 병존, 07-27 09시 하향 판정 그대로 유지. [2026-08-05 심층 추가] ⓐ ⚠️ 자기수정 — 기존 confidence·rationale이 인용한 The Athletic "Terms not an issue"의 발행일 2026-08-03은 오류이며 실제는 2026-07-21이다. 이 항목을 최신 긍정 근거로 쓰지 말 것. ⓑ 부상 이력(Soccerway) — 2020·2021 근육, 2023-02 허벅지, 2023-11-10~12-27(복귀 20분 만에 재발), **2024-04-14~2024-08-27 발목 약 4.5개월 시즌아웃**(종아리 병발), 2025-01-20~02-21, 2025-10-12~10-31 발목. 패턴은 햄스트링이 아니라 발목·종아리·허벅지 복합. 28세 + 재발 이력 + 세리에A 적응 실패가 겹친 프로파일이며, 밀란이 원가 €19m 대비 €15m 손절을 받아들이려 한 것이 이를 뒷받침한다. ⓒ 25/26 밀란 1년차 실적 — 19경기 13선발 1,035분 1골 1도움, 경고 5·퇴장 1. 20세 바르테사기에게 주전을 내줬고 매체가 일관되게 "실망스러운 시즌"으로 서술. 직전 24/25 브라이턴은 PL 30경기 1골 1도움. ⚠️ 소스 불일치: ESPN은 선발 9회로 기재(LiveScore 13선발) — 인용 시 출처 명기. ⓓ 밀란 내부 모순 — Gazzetta는 "아모림이 윙백을 선호해 붙잡는다"로 쓰지만 복수 보도는 아모림이 좌측에 바르테사기·살레마커스를 선호한다고 적는다. veto의 실제 동기가 전술 선호인지 "대체자(마즈라위) 확보 전까지 뎁스를 못 비운다"는 리스크 관리인지 1티어 직접 확인 없음. ⓔ 실측 한계는 루헤리와 동일 — @dom/@tight·국면 분리 표본 없음. 또한 전술 스타일(오버랩 vs 인버티드·크로스·수비 안정성)에 대한 기사 근거가 사실상 부재해 프로파일은 실측 .946에만 의존한다. ⓕ 경쟁 링크였던 데포르티보 라코루냐는 08월 보도에서 완전 소멸 — 추적 종료. ⓖ 인용 금지 소스: cryptobriefing.com(암호화폐 사이트의 축구 SEO 기사), the4thofficial.net "€14m full-back"(어느 1티어와도 수치 불일치). sempremilan·milanreports·football-italia·getfootballnewsitaly·milannews는 자체 취재가 아닌 1티어 번역·중계이므로 티어는 원출처(Gazzetta/Tuttosport/Moretto/Athletic) 기준으로 판정할 것.','에스투피냔','2026-08-04');
INSERT INTO transfer_targets VALUES(77,'AVL','2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg','CM','LDM','CONFIRMED','33414775548X6447877220320',43.60000000000000142,51.79999999999999716,6,7.620000000000000106,'dm_dlp','Roaming','dm_dlp','Roaming',0.7259999999999999787,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','Romano/Ornstein/Sky Germany 하이잭 보도(€70m 합의 임박); SofaScore player/1518931 (6 Bundesliga ~2026-05-16)','CONFIRMED — 합류 확정. 실측 신뢰 HIGH(6경기 전부 45분+, 363pt, fit 0.812). / 2026-07-15: 구단간·개인 합의 완료, 공식 발표만 대기 — CONFIRMED 유지. / 2026-07-18: 구단 공식 발표 — 완료.','만잠비',NULL);
INSERT INTO transfer_targets VALUES(91,'AVL','2026-summer','João Palhinha',NULL,364612,'Bayern Munich','DM','LDM','HIGH','002112323345365465X611221',53.70000000000000284,44.0,6,6.919999999999999929,'dm_holding','Ball-Winning','dm_widehalf','Build-Up',0.7089999999999999636,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다.','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입. / [2026-08-03] 경쟁 축 캐비앗: 뉴캐슬은 감독 공백으로 집행력 부재 · 자금은 증가 가능 — 두 방향이 상쇄돼 순효과는 미확정.','팔리냐','2026-08-06');
INSERT INTO transfer_targets VALUES(92,'AVL','2026-summer','João Palhinha',NULL,364612,'Bayern Munich','DM','RDM','HIGH','002112323345365465X611221',53.70000000000000284,44.0,6,6.919999999999999929,'dm_holding','Ball-Winning','dm_dlp','Roaming',0.7379999999999999894,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다.','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입. / [2026-08-03] 경쟁 축 캐비앗: 뉴캐슬은 감독 공백으로 집행력 부재 · 자금은 증가 가능 — 두 방향이 상쇄돼 순효과는 미확정.','팔리냐','2026-08-06');
INSERT INTO transfer_targets VALUES(95,'AVL','2026-summer','João Gomes','주앙 고메스',1015267,'Wolverhampton','DM/CM','LDM','CONFIRMED','11111551335X5443756411211',47.0,47.10000000000000142,6,6.650000000000000355,'dm_dlp','Roaming','dm_dlp','Roaming',0.7890000000000000346,unistr('틸레만스 대체 영입 — 클럽간 합의(초기 £34.6m+애드온 £4.3m, 총 ~£38m), 금주 메디컬 예정. 아틀레티코행이 멘데스-구단 갈등으로 결렬된 것을 빌라가 인터셉트. [2026-07-17 실측+3축] 최근 6경기(45분+): 태클 3.7·듀얼 7.0·kp .3·xA .04 — 기능=순수 볼위너+박투박 엔진(카마라형). 움직임 최근접 dlp/Roaming .797(LDM — 우측 배치 .638로 좌측 우세). 기능축 우선(obs#31)으로 처방 dm_holding/Ball-Winning. [2026-07-18 재확인] 메디컬 금요일(7/17) 진행 — 포르투갈 캠프 이탈·귀국 확인, 개인조건 2031년 계약 합의(Schira). 공식 발표 임박. [2026-07-28 FC26 통합 확인] 기능축 우선 처방(dm_holding/Ball-Winning) 유지. 캐비앗: FC26 숙련은 boxcrasher/widehalf/dlp/cm_dlp — holding 마커 없음. 압박검증·슬라이딩태클 PS는 볼위닝 기능 지지. [2026-07-29 홀딩 처방 재검증 — 유지 확정] 현행 커널 재검산: dlp/Roaming .797 정확 재현(stale 아님), holding/Ball-Winning은 .45로 움직임 불일치. 그러나 ①실측 홀딩 동료와 직접 유사 — 온아나 그리드 .835/카마라 .805 (둘 다 움직임 코사인은 dlp .87이었으나 기능축으로 holding 처방된 동일 패턴, obs#32) ②기능=창조 전무(kp .3·xA .04) — dlp 지시는 전개 산출 없는 선수에게 공급 책임 부여하는 모순 ③요구역할=카마라 장기부상 중 앵커 대체+obs#27 블록 전제. 3축 모두 holding 지지 → dm_holding/Ball-Winning 유지. 숙련 캐비앗 대응: holding 미숙련 페널티 확인 시 차선은 dm_boxcrasher/Balanced(.701, 숙련 보유+박투박 기능 부합)이며 dlp가 아님. left-release-A 프리셋의 LDM dlp 공급 요건은 고메스 기능으로 충족 불가 — 진성 DLP형(사라·베르그발) 영입 또는 boxcrasher 절충 필요.\u000a\u000a[2026-07-31 H안] 프리셋 LDM 선발로 승격되며 처방을 dm_holding/Ball-Winning → **dm_dlp/Roaming .789**(숙련✓)로 교체. 커널 교체로 만잠비(.726)와 순위가 역전됐다(이전 만잠비 .812 > 고메스 .797). ⚠️ 캐비앗: 고메스도 기능상 볼위너이고(창조 kp .3·xA .04) 스쿼드에 진성 DLP가 없다 — 적합을 위해 기능 정합을 포기한 칸이다. [2026-08-05 역할 처방 확정 — 기존 dm_dlp/Roaming 유지] LDM(x=38) 전수 채점: dm_dlp/Roaming 0.789 → dm_dlp/Build-Up 0.714(Δ.075) → dm_boxcrasher/Balanced 0.685 → dm_holding/Roaming 0.669(Δ.120) → dm_dlp/Defend 0.578 → … → dm_holding/Ball-Winning 0.452(9/10). RDM에서는 0.680으로 LDM보다 Δ.109 낮아 **좌측 배치 확정**. [기능축 충돌은 계승 — 명시적 지불] 툴 FUNC_AXIS가 고메스를 {role:dm_holding, mode:prefer}로 두고 why에 "창조 전무(kp .3 · xA .04)로 기능축은 볼위너. 다만 dm_dlp 적합이 뚜렷이 높아 프리셋은 dlp를 채택 — 적합을 위해 기능 정합을 포기한 칸"이라 적어뒀다. 2026-08-05 이벤트 측정이 그 근거를 **독립 재현**했다: 키패스 0.30/90(FUNC_AXIS의 kp .3과 정확히 일치). dm_holding/Roaming으로 돌리면 .789→.669로 Δ.120 손실이고 동점 임계(.03)의 4배라 타이브레이커 논리로 정당화되지 않는다 → dm_dlp/Roaming 유지. [카마라와의 3선 분담] 겹침 .715로 가용 피봇 조합 중 최저(고메스↔오나나 .874가 최고 중복, 카마라↔오나나 .814, 카마라↔바클리 .806, 고메스↔바클리 .753). 좌우는 열중심 고메스 46.8 vs 카마라 62.3, 깊이는 수비3rd 고메스 7% vs 카마라 11~15%. **기능 분담은 역할 이름이 아니라 슬롯+선수 능력치가 만든다** — 이벤트 per-90: 고메스 태클 3.52 vs 카마라 2.33 / 카마라 패스 52.5 vs 42.5 · 키패스 0.93 vs 0.30 · 인터셉트 1.40 vs 0.70 · 롱볼 정확도 62.5% vs 44.0%. 즉 카마라 배급·읽기, 고메스 압박·차단. ⚠️ 표본 교란: 카마라는 25-11~26-01 빌라(4위권), 고메스는 26-02~05 울브스 — 약팀 미드필더는 구조적으로 패스가 적고 태클이 많아 교란 방향이 관측과 일치한다. 비율 지표(롱볼 정확도 18.5pp 차·키패스 3.1배)가 더 신뢰된다. ⚠️ 불변규칙 7 — 이 실측은 울브스 체제 표본이므로 개인 위치 성향 기준선으로만 쓰고 에메리 3선 구조의 근거로 쓰지 않는다. 빌라 소속 공식전 표본은 0경기다(프리시즌 5경기는 SofaScore 선수별 데이터 전건 404).'),'ESPN(1티어, sources) fee agreed ~€40m ; Fabrizio Romano(1티어) "here we go" £34.6m+£4.3m (2026-07-16~17) ; SofaScore API player 1015267 (2026-07-17, 최근 6경기 45분+)','CONFIRMED — 1티어 이중 확인(ESPN+Romano here we go), 메디컬만 남음(만잠비·틸레만스 선례와 동일 단계). 실측 HIGH(6경기 전부 45분+). / 2026-07-18: 메디컬 진행 — 발표만 대기.','고메스',NULL);
INSERT INTO transfer_targets VALUES(97,'AVL','2026-summer','Julián Quiñones','훌리안 퀴뇨네스',843114,'Al-Qadsiah','ST','ST','DEAD (STALE — 빌라 특정 보도 2026-07-16 이후 15일 무소식)','10X5114763023410113100100',57.0,67.0,6,7.679999999999999716,'st_false9','Attack','st_false9','Attack',0.8319999999999999619,unistr('왓킨스 대체 후보 — 멕시코 월드컵 4골 1도움(잉글랜드전 득점 포함)으로 빌라 스카우트 반함, 대리인 접촉 "최근 강화"(Tavolieri). 사우디 알카디시아 2029 계약·릴리스 $200m이 장벽, 첼시·헤노아·아틀레티코 경쟁. [2026-07-17 실측+3축] 최근 6경기(45분+, 사우디리그): xG 1.10·7골·xA .31·평점 7.68 — 산출 폭발적이나 리그 수준 캐비앗 필수. 움직임 st_false9/Attack .832 최상(드롭·링크형 피니셔), 기능은 순수 피니셔. [2026-07-18 전술핏 분석] ①아키타입: 기라시와 그리드 .914(사실상 동일 유형 — false9 드롭형 피니셔 2명이 후보군), 듀란 실측과 .876. obs#18 "듀란형 ST(스피드+파워)" 니즈 대조 — FC26 PAC 88(왓킨스 77·기라시 72 압도)+PHY 83으로 후보군 중 듀란형 정의 최근접. ②10번 공존성: 로저스 CAM 그리드와 겹침 .750 — 왓킨스(.891)보다 낮음. 실측 중심이 우채널(57.0) 드리프트라 중앙-좌 성향 10번과 상보적 — 로저스 잔류 시나리오에서도 공간 충돌 개선. ③왓킨스 3역 임무 대조: 박스 점유(xG 1.10)·드롭/링크(false9 .832)·채널런(우측 드리프트) 전부 충족 — 단 좌우 방향이 왓킨스와 반대(왓킨스 좌, 퀴뇨네스 우). ④수비: 자기진영 .127 — ST 슬롯은 프레스 첫줄이라 미드블록 이슈 아님(프레스 강도 실측은 미확보 캐비앗). 커널 확정 false9/Attack .832, 공중 플랜B 대안 target/Balanced .726(아브라함 역할 겸임 가능). 최대 리스크는 사우디 리그 수준 보정과 29세(리세일 없음). [2026-07-19 재검증] Sky Sport(Tavolieri, tier 애매) 접촉 강화 확인, 정식 오퍼는 아직 없음. Romano(1티어)는 첼시 관련설만 부인 확인 — 빌라 진전과 무관. 등급 유지. [2026-07-20 21시(4차) 재검증] Sky Sports 인용 주장(GiveMeSport 재인용, 원문 미확인)으로 빌라 문의설 — 원문 크로스체크 실패, 등급 유지. [2026-07-27 21시 최신화] Sacha Tavolieri(Sky Sport) 경유: 월드컵 활약 이후 빌라 스카우트가 확신, 대리인 접촉 "최근 강화" — 단 공식 오퍼는 아직. 첼시·제노아·아틀레티코와 경쟁, $200m 바이아웃은 협상용 명목가로 판단. [2026-07-28 FC26 통합 확인] 실측 0.832 + 숙련 st_false9+ 일치 + 칩슛/래피드/PAC88·점프95 — 처방 확정. [2026-07-29 14시 재확인 — 유지] 공식 bid 없음, 대리인 접촉 강화(WC 후). 장애물: 사우디 고임금(감봉 필요)+명목 $200m 릴리즈 클로즈(협상용). SCR 벌금 맥락상 유출 선행 필요. [경쟁구도 2026-07-30] 빌라 우위(사실상 단독) — 최대 경쟁자였던 첼시 링크를 Romano(1티어)가 "사실무근"으로 직접 부인, 그 외 명명된 경쟁 클럽 확인 불가. 단 경쟁 부재의 이유가 매물성 부재일 가능성: 알-카드시아가 월드컵 활약 후 "untouchable" 규정, 2026-05-25 계약 연장(2029), 사우디 고액 연봉이 구조적 장애. 소속 정정: Al-Qadsiah. "릴리즈 클로즈 $200m" 주장은 3티어 미검증 — 신뢰 금지. 8월까지 공식 입찰 부재 시 MEDIUM 하향 검토(현재 경과 14일 = 규칙상 초과 아님, 경계).\u000a\u000a[2026-07-31 STALE 전환 — §4-3] 빌라 특정 최신 보도가 2026-07-16(Sacha Tavolieri, 2티어 — 측근 정보 취득·공식 오퍼 없음)에서 멈춰 15일 경과, 14일 기준 초과. ⚠️ 전환 사유는 **경쟁 열위가 아니다** — 경쟁 링크는 사실상 0이다(첼시 입찰설은 Romano가 7/11 직접 부인, 제노아·AT마드리드는 Transfermarkt 루머란에만 존재). 오히려 **매물성 자체의 부재**가 유력하다: 알-카드시아가 월드컵 전 2029년까지 재계약했고 Ben Jacobs가 not for sale로 규정했다. 사우디 고연봉 삭감도 장애물. 실측 자산(map25 · st_false9/Attack .832 숙련✓)은 보존한다 — ⭐ 이 값은 새 커널에서도 불변이고 **잭슨 .752를 크게 웃도는 ST 최고치**라 매물성이 열리면 즉시 재검토 대상이다.'),'Sacha Tavolieri(Sky Sports 계열, 2티어) 컨택 강화 보도 ; TeamTalk "intensify contact" ; Football Insider ; SofaScore API player 843114 (2026-07-17, 사우디리그 최근 6경기 45분+); Sacha Tavolieri; Sky Sports(Yahoo 경유); FootballPlace; Tribuna; InsideFutbol','MEDIUM-HIGH 유지 — 접촉 강화 확인되나 공식 오퍼 부재, 경쟁 클럽 다수로 HIGH 미달.','퀴뇨네스','2026-07-16');
INSERT INTO transfer_targets VALUES(121,'AVL','2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg → Aston Villa','CM/AM','CAM','CONFIRMED','25012X7564332351311200020',46.46999999999999887,61.39000000000000056,4,7.480000000000000426,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.8169999999999999484,'합류확정 멀티포지션 부여: 스위스 대표팀 전진 배치 실측 — 월드컵 2경기(캐나다 8.1·알제리 7.8)+친선 2경기(호주·요르단, lineup pos=F) 통합 4경기 168pt, 중심 tool(46.5,61.4). CAM 배치 cam_halfwinger/Balanced 0.817 — 클럽(프라이부르크) 딥롤 그리드의 CAM 적합(0.575)과 달리 대표팀 전진 표본에서 10번 적합 뚜렷. 월드컵 3골(8강 진출)이 이 전진 롤에서 나옴 — 클럽 box-to-box와 별개로 세컨드 스트라이커/10번 활용 여지 실증.','SofaScore API player 1518931 — events 12813019/15186821(WC)/16118856/15891673(친선) (수집 2026-07-21)','CONFIRMED(합류) — 실측 신뢰 MEDIUM: 대표팀 표본 4경기(친선 2 포함) 168pt, 클럽 CAM 순수 표본 없음. 스위스가 실제로 전진 배치해 검증된 롤.','만잠비',NULL);
INSERT INTO transfer_targets VALUES(122,'AVL','2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg → Aston Villa','CM/AM','LM','CONFIRMED','25012X7564332351311200020',46.46999999999999887,61.39000000000000056,4,7.480000000000000426,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.6460000000000000186,'합류확정 멀티포지션 부여: LM 순수 출전 표본 없음 — 대표팀 전진 그리드(4경기 168pt)의 LM 슬롯 재배치 적합 0.700(wm_insidefwd/Balanced), 클럽 그리드 기준은 0.607. 좌 하프스페이스 커버는 가능하나 터치라인 고정형이 아닌 중앙 회귀 성향 — 로테이션/변형 옵션 등급.','SofaScore API player 1518931 — 대표팀 4경기 통합 그리드 슬롯 재배치 계산 (수집 2026-07-21)','CONFIRMED(합류) — 실측 신뢰 LOW-MEDIUM: LM 포지션 순수 표본 부재, 전진 그리드의 재배치 적합 계산치.','만잠비',NULL);
INSERT INTO transfer_targets VALUES(123,'AVL','2026-summer','Nicolas Jackson',NULL,NULL,'Chelsea','ST','ST','HIGH (정체 — 07-28 이후 단계 전진 없음)','457725X496434211211100000',48.0,68.79999999999999716,6,7.450000000000000177,'st_advanced','Support','st_advanced','Support',0.7520000000000000017,'로저스 매각(첼시 £117m)으로 확보한 자금 재투자 대상, 에메리-비야레알 인연. [2026-07-24 갱신] 가르나초 CONFIRMED로 정리된 후에도 별개 딜로 논의 지속 확인 — 첼시가 £65m 요구가 명확히 설정(협상 기준가), 잭슨 본인도 정규 출전시간을 위해 빌라 이적에 열려있음("open to a move"). 로마노(1티어) "에메리 여전히 팬" + 양 구단 논의 지속 확인. 빌라 재정 제약으로 £60m 이하 필요 시사(협상 지속 근거) — 협상 단계 진입으로 등급 상향. [2026-07-27 21시 최신화] Sky Sports(1티어) 공식: 빌라가 조건 타진 중이며 "positive discussions" 진행. 첼시 호가 £60m+, 빌라는 클럽 레코드 경신 예상. 로저스·가르나초에 이은 첼시-빌라 세 번째 딜로 그림 완성. [2026-07-28 FC26 통합 확인] 실측 0.752 + 숙련 st_advanced+ 일치 — 확정. Support 포커스는 하강 링크 성향(실측)과 게임체인저/테크니컬 PS 부합. [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(7/28): 첼시·선수 측과 직접 협상 진행 중(영구 or 대여), 합의 아직 없음. 첼시 호가 £65m(영구 선호), 빌라 클럽레코드 경신 준비 보도(GMS). 호재: 첼시가 웰벡(브라이튼) 영입 검토 — 잭슨 방출 여지 확대. [경쟁구도 2026-07-30] 빌라 우위(단독) — 1티어가 협상 단계를 확인한 클럽은 빌라뿐이고 경쟁은 무명 "주시" 수준(CaughtOffside 3티어). 선수 선호는 상충(TEAMtalk 7/24 에메리 재결합 적극 vs The Sun 7/20 첼시 잔류 희망)이나 최신성 기준 7/27 Plettenberg 협상 진행 보도가 우세. 병목은 클럽 경쟁이 아니라 £65m 구단기록 + 왓킨스·에이브러햄 유출 선행. 날짜함정: "뉴캐슬 preliminary contact £80m"은 2025-07-28 기사로 본 창과 무관. [2026-08-03 21시] 구조적 제약 확정 — PL 규정상 **같은 PL 클럽에서 한 시즌 임대는 1명까지**이고, 빌라는 이미 가르나초로 첼시 임대 쿼터를 소진했다(Football London·Ryan Taylor). 따라서 Plettenberg가 07-28에 남겨둔 "영구 or 대여" 양갈래에서 **대여 경로는 규정상 봉쇄**되고 완전이적만 남는다. 이는 "첼시가 완전이적 선호"라는 상대 의향을 **규정 차원의 강제**로 굳히는 것이라, 빌라가 £60m+ 자금을 실제로 마련하지 못하면 딜 자체가 성립하지 않는다. 단계 변화는 아니므로 HIGH 유지. [2026-08-05 심층 — HIGH 유지 + 정체 플래그] 등급 근거는 유효하나 08-01~05 사이 1티어발 진전이 0이다. 협상 단계를 확인한 마지막 1티어 보도는 07-28(Plettenberg/Romano)이고, 공식 오퍼·금액 합의·메디컬·here we go 전부 없다. 07-24 이후 12일간 단계 전진 증거 없음 → HIGH는 유지하되 정체 상태로 표기. ⑴ HIGH 지탱 근거 강화: 1티어 3개 축 독립 확인(Romano 07-20·07-28 / Ornstein·The Athletic 07-22 완전이적 시 4년 계약 골격 / Plettenberg 07-27~28 첼시·선수 측 직접 협상). 경쟁 전멸 — 바이에른은 €65m 매수옵션을 40경기 출전 조건 미달로 포기해 완전 소멸, 토트넘 참전설은 Daily Mail 08-04 보도 당일 스퍼스 전담 Alasdair Gold가 부정, 뉴캐슬 링크는 2025년 창 잔상이다. 사우디 링크는 0건. §2-1 판정 빌라 단독 우위. ⑵ 08월 신규 구조 변화 — 첼시가 08-01 대니 웰벡(브라이턴, 2년) 영입을 공식 발표해 ST/CF 자원이 8명이 됐다(조앙 페드로·웰벡·에메가·델랍·기우·잭슨·음훼카·사트파예프). 여기에 25/26 리그 10위로 유럽대항전 없음(상금·중계권 £80m+ 결손) + 26/27 SCR·SSR 신규 규정 + PL 25인 한도가 겹쳐 첼시는 반드시 판다. 잭슨 아니면 델랍이며 시장가는 잭슨이 훨씬 높다. ⑶ 상향(임박) 차단 요인: 첼시 £65m 고정 vs 빌라 "£60m 미만이어야"(Telegraph)로 £5m+ 격차 미해소. 임대 경로는 Romano 07-28로 규정상 완전 봉쇄 확정(PL 동일구단 임대 1명, 가르나초가 소진) → £60m+ 일시 완전이적만 남았고 이는 07-17 만잠비 £59.5m 직후의 구단 기록 재경신을 뜻한다. Ben Jacobs가 언급한 "£10m 임대료+조건부 의무매입" 안은 이 규정과 충돌해 성립 불가. ⑷ 양방향 교착 — Tanswell(The Athletic 07-28): 빌라는 왓킨스·에이브러햄 중 누가 나갈 경우에 대비해 대안을 평가 중이지 능동적으로 밀어내지 않는다 / TEAMtalk 07-24: 잭슨이 와야 빌라가 왓킨스 이적에 열린 자세가 된다. 그런데 왓킨스 맨유행은 08-04 기준 냉각(맨유가 Sesko 보유, 지르크지 매각 선행 필요) → 교착 해소 트리거가 사라졌다. ⑸ Sky Sports(Dharmesh Sheth, 07-28)가 "빌라가 이 영입을 피할 수도 있는 이유" 영상을 자체 방송 — 1티어 매체의 명시적 회의론. [배치 서사 vs 실측 2026-08-05 — 불변규칙 3] 복수 보도가 "천성은 ST지만 에메리 팀에서는 주로 측면(좌측)에서 뛸 것"이라 예상하나, 실측 그리드를 슬롯별로 채점하면 ST(x=50) st_advanced/Support .752 > CAM(x=50) cam_playmaker/Roaming .742 > LM(x=14) wm_insidefwd/Balanced .667 > RM(x=85) .661이다. 좌측 배치 서사는 실측이 지지하지 않는다(LM이 ST보다 .085 낮음). 다만 ST와 CAM이 Δ.010으로 사실상 동률이라는 것이 새 사실 — 상위 2대역(공격3rd 32%+공격미들 43%)에 75%가 몰린 높은 원톱이면서 CAM 대역을 함께 점유한다. 좌우 편향은 좌 43%/중앙 20%/우 37%로 중앙형이며 뚜렷한 좌측 드리프트는 관측되지 않는다. [ST 슬롯 상대 평가] 잭슨 .752(Δ.115)는 현 주전 왓킨스의 25/26 시즌 그리드 .722(Δ.032, 동점구간)보다 높고 역할 정체성도 선명하다. 단 잭슨↔왓킨스 코사인 .911로 같은 구역을 쓰는 대체재이지 보완재가 아니다 — 병행 기용 시 ST 슬롯이 중복된다. 높이 차이: 잭슨은 상위 2대역 75%·수비3rd 0%로 내려오지 않고, 왓킨스는 64%·수비미들 13%로 더 넓게 움직인다.','Fabrizio Romano(1티어) 관심·에메리 각별 신뢰 확인 ; Football Insider(2티어) £60-65m 요구 ; Yahoo Sports "step up talks" ; SofaScore API player 1085381 (2026-07-21) ; thehardtackle(2026-07-19,21) 논의/가격 설정 ; Yahoo Sports(잭슨 open to move) ; teamtalk(2클럽 논의 중) ; Romano X 2079473534951211218 ; teamtalk nicolas-jackson-villa-break-transfer-record (재검증 07-26); Sky Sports; BBC(gossip); TeamTalk; Africasoccer ; [08-05 심층] Ornstein/The Athletic(1티어) 2026-07-22 4년 계약 골격 via https://uk.sports.yahoo.com/news/why-aston-villa-sign-nicolas-180000917.html ; Plettenberg/Sky Germany 2026-07-28 https://www.caughtoffside.com/2026/07/28/aston-villa-nicolas-jackson-transfer-florian-plettenberg/ ; Romano 2026-07-28 임대 불가 확정 https://www.givemesport.com/aston-villa-nicolas-jackson-chelsea-transfer-romano-update/ ; Sky Sports(Sheth) 회의론 영상 2026-07-28 https://www.skysports.com/football/video/12606/13567768/nicolas-jackson-why-aston-villa-may-avoid-signing-striker-from-chelsea ; 웰벡 첼시 이적 2026-08-01 https://www.espn.com/soccer/story/_/id/49478554/danny-welbeck-chelsea-brighton-premier-league-transfers ; BBC 알론소 발언 2026-08-04 ; Daily Mail(Rosser) 2026-08-04 스퍼스 참전 → 당일 football.london 부정 https://www.sportsmole.co.uk/football/spurs/transfer-talk/news/nico-or-nic-no-jackson-to-tottenham-transfer-truth-revealed_602396.html','HIGH 유지 — 1티어(Sky) 협상 진행 확인, 기록적 이적료 임박 분위기. [2026-08-03 21시] 임대 경로 봉쇄는 규정 근거(PL 동일구단 임대 1명)라 보도 티어와 무관하게 성립 — 단, 가르나초 딜이 임대 구조라는 전제에 의존한다(현재 조건부 임대+£40m 완전이적 옵션으로 보도됨). [2026-08-05 심층 추가] ⓐ ⚠️ 실측 출처 미확정(검증 백로그) — source의 "SofaScore API player 1085381 (2026-07-21)" 6경기 표본이 어느 대회 것인지 DB에 기록돼 있지 않다. 잭슨은 25/26 시즌 전체를 바이에른 뮌헨 임대로 보냈고(2025-09-01~2026-06-30) 2026 월드컵에 세네갈 대표로 출전했다. 따라서 2026-07-21 기준 "최근 6경기"는 바이에른 25/26 경기·월드컵 경기·혼재 중 어느 것도 가능하다. club 필드의 "Chelsea"는 소속 구단이지 측정 출처가 아니다. 월드컵 표본이 섞였다면 클럽 전술 맥락과 다른 데이터이므로 재수집이 필요하다. → 다음 SofaScore 접근 시 event id 목록을 확인해 rationale에 명기할 것. ⓑ 선수 의사 상충 — TEAMtalk(Graeme Bailey) 07-24 "에메리 재회에 매우 열려 있고 완전이적을 원한다" vs The Sun 07월 "첼시에 남아 알론소 밑에서 증명하기로 결심" vs Daily Mail(Jack Rosser) 08-04 "보장된 출전시간을 찾아 떠날 준비". 본인 직접 발언 원문은 이번 창에 확보되지 않았다(DSPORTS "나는 첼시 선수다"는 2025년 창 발언). 공통분모는 "출전시간 보장 요구"이며, 바이에른에서 전 대회 선발 15경기에 그친 경험이 결정 변수다 — 빌라가 왓킨스 위 서열을 보장하지 못하면 본인 동의가 흔들릴 수 있다. ⓒ 알론소 08-04 홍콩 기자회견(BBC, 1티어)은 중립~잔류 톤 — "니코는 훌륭한 선수", "함께 있어 기쁘다", "하루하루 옵션을 점검하겠다", "시장은 아직 3주 남았다". 매각 확정 뉘앙스가 아니다. 알론소는 전통적으로 장신 타깃형 9번을 선호해 조앙 페드로·에메가가 그 틀에 더 맞는다는 분석이 병기된다. ⓓ 계약이 2033년까지라 레버리지는 전적으로 첼시에 있다 — 급히 팔 이유가 없다는 점이 £65m 고정 호가를 지탱한다. ⓔ 부상 이력(Transfermarkt): 25/26 무부상, 24/25 햄스트링 58일(10경기), 23/24 발목 56일, 22/23 고관절 57일(15경기), 20/21 근섬유 파열. 누적 결장은 적으나 "한 시즌 1회 8주급" 근육·관절 패턴이 반복된다. 2026 월드컵 + 2025 AFCON 참가로 여름 부하 누적이 리스크. ⓕ ⚠️ §2-0 휴리스틱 실패 사례 기록 — 이 건에서는 "나이 표기로 재순환 기사를 거른다"는 규칙이 오탐을 낸다. 2026년 창에 실제 발행된 기사들이 잭슨 나이를 제각각 틀리게 적었다(TEAMtalk 07-24 "25" 정확 / GiveMeSport 07-24 "23" / Yahoo 07-20 "27" / Yahoo 08-04 "24"). 마지막 건은 "24세"로 쓰면서 본문에서 08-05 홍콩 유벤투스 친선전을 언급해 명백히 2026-08 발행이다. → 이 선수에 한해 대체 판별 지표를 쓸 것: 로저스 첼시 £117m · 가르나초 빌라 임대 · 만잠비 빌라 £59.5m(07-17) · 웰벡 첼시 이적(08-01) · 알론소가 현 감독이고 마레스카는 전 감독 · 첼시 25/26 리그 10위 유럽대항전 없음 · 맨유 감독 Michael Carrick · 바이에른이 매수옵션 포기(2025년 기사는 "관심 중" 단계). ⓖ 인용 금지: newsstation2.com 2026-08-01 "빌라-첼시 합의·메디컬 예정"은 콘텐츠 팜이며 1·2티어 교차확인 0건, 08-04 Daily Mail·BBC가 여전히 미해결로 서술해 사실상 반증됐다. BBC 가십 07-29 "첼시가 로저스 대가로 Tosin+잭슨+현금 제안"은 로저스 딜이 07-20경 이미 합의된 것과 시간순 모순이라 근거로 쓰지 말 것.','잭슨','2026-08-04');
INSERT INTO transfer_targets VALUES(125,'AVL','2026-summer','Iliman Ndiaye',NULL,NULL,'Everton','RW','RM','DEAD (강등 MEDIUM — Al-Hilal 개인합의 우위, 빌라는 £70–75m 호가에서 이탈)','112273215X101370002410001',71.20000000000000284,63.39999999999999858,6,6.870000000000000106,'wm_winger','Attack','wm_winger','Attack',0.8249999999999999556,'로저스 대체 우측 자원 후보, 맨유와 경쟁. [2026-07-27 21시 최신화] Fabrizio Romano(1티어): "몇 주 전 빌라와 약간의 대화가 있었다" — 초기 단계 확인, 맨유도 경쟁(라쉬포드 이적 우선 필요로 진전 더딤). 에버턴 £70m 밸류에이션이 핵심 걸림돌. [2026-07-28 FC26 통합 확인] 실측 0.883 명확(2위 winger 0.825) — 숙련은 wm_winger+뿐이나 데이터 우선(맥긴 선례, 숙련은 스탯 너프 아님). DRI86/테크니컬/#드리블러가 인사이드 포워드 기능 지지. [2026-07-29 14시 재확인 — 유지] Romano 확인: "빌라가 몇 주 전 대화했다" — 맨유·해외 클럽과 경쟁. 에버튼 ~£70m 요구(계약 연장 협상 정체). 탐색 단계, 서머빌 대안 병행 검토. [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .864(전 후보 최고 = 형태 최근접), 침투 서명 전방 0.63·자기진영 0.15. 프로필은 브리프 정합이나 £70m 밸류에이션이 실행 장벽 — 형태 순위 1위/실행 가능성 하위. [경쟁구도 2026-07-30] 경쟁 우위 — 단계 비교 Al-Hilal(개인합의+구단간 협상 개시, Romano 1티어) > 맨유(관심) > 빌라(접촉 후 후퇴). Romano가 빌라의 £70–75m 이탈(baulked)을 확인. 선수는 에버턴 재계약 4회 거부, 에이전트가 사우디 입찰 독려 = 빌라 선호 정황 없음. 예산축도 동일 방향: £70m은 잭슨 £65m과 같은 지갑을 다툼. 1티어 내부 충돌 기록: Athletic Boyland은 "구단간 협상 미개시"로 Romano를 부분 반박.','Fabrizio Romano(1티어) 컨택 확인 ; astonvillanews.co.uk £60m 딜 ; Arsenal Pulse/Lorenzo Jabota(3티어, 보조 근거) ; SofaScore API player 914309 (2026-07-21); Fabrizio Romano; ESPN; Yahoo Sports; AstonVillaNews; bet365 News','MEDIUM-HIGH 유지 — 1티어가 초기 대화 확인, 공식 오퍼는 아직 없음. / [2026-07-30] MEDIUM 강등이나 삭제하지 않고 DEAD 숨김(실측 .883 보존, 사용자 결정). / 🔄 **[2026-07-31 obs#100 — 커널 교체 후 재산출]** 옛 기준(obs#93·#94 이전) 잔존값을 정정했다. 브라우저에서 툴 `placedMap`·`cmpCos`를 직접 호출해 산출(컨텍스트 노트 2), 회귀 게이트 하지무사 .821 재현 확인. 은디아예 RM(x=85): .580 (wm_insidefwd/Balanced) → **wm_winger/Attack 0.825**.','은디아예','2026-07-21');
INSERT INTO transfer_targets VALUES(126,'AVL','2026-summer','Gabriel Sara',NULL,NULL,'Galatasaray','CM','RDM','DEAD (강등 MEDIUM — 알-힐랄 경쟁 우위, 빌라 공식 오퍼 없음)','72226XX899678845644522222',48.20000000000000284,56.20000000000000284,6,7.349999999999999645,'dm_dlp','Roaming','dm_dlp','Roaming',0.6019999999999999796,unistr('티엘레만스 이적·카마라 부상 공백 메우는 중앙 자원 후보. 팔리냐와 함께 검토 중. [2026-07-27 21시 최신화] TeamTalk(2티어): 빌라·뉴캐슬이 대리인과 접촉(£25m). 단, 빌라가 동일 에이전트 라인(주앙 고메스)으로 이미 미드필더를 영입해 긴급성 낮아짐 — 나폴리·뉴캐슬도 경쟁. 갈라타사라이는 매각 의향 있으나 공식 오퍼는 아직. [2026-07-28 FC26 통합 재판정] 기존 처방 dm_holding/Ball-Winning은 FC26 프로필과 불일치(차단력65·태클66/59 — 볼위닝 기능 없음). 실측 argmax dm_dlp/Roaming 0.607 + 긴패스85·커브84·데드볼/예리한패스/인벤티브 PS = 배급형 → dm_dlp/Roaming으로 교정. 캐비앗: FC26 숙련은 CM/CAM 계열(cm_b2b+·cam_playmaker+)뿐이라 RDM 기용 시 역할 숙련 마커 없음, 적합 절대값도 0.607로 낮음. [2026-07-29 14시 재확인 — 유지] 빌라·뉴캐슬이 측근 접촉(공식 오퍼 없음), Football Insider "빌라 선두". 갈라타사라이 최소가 €35m(Fanatik) — 투람 영입 재원으로 매각 계획. 선수 PL 이적 긍정적. [경쟁구도 2026-07-30] 대등 — 뉴캐슬이 동일 원출처(TEAMtalk)·동일 단계(대리인 접촉, 공식 입찰 전)로 병렬. 나폴리는 라비오 결렬 시 선회하는 조건부 2순위. 선수 측 가점: 사라 본인 7/28 공개 발언 "PL에서 뛰는 꿈이 있다"(Hürriyet). 갈라타사라이는 €30m 초과(일부 €35–40m) 아니면 불응, 오칸 부루크 공개 반대, 계약 2029. 하향 트리거 = 뉴캐슬의 실제 입찰 선행.\u000a\u000a[2026-07-31 하향 MEDIUM-HIGH→MEDIUM — §2-1 경쟁 보정] **알-힐랄이 갈라타사라이와 구단간 협상을 개시**하고 보너스 포함 €30m(일부 보도 €40m) 공식 제안이 임박했다(Milliyet·Fotomaç·A Spor 등 터키 2티어 복수, 2026-07-30). 빌라는 **대리인 접촉·공식 오퍼 없음**(Football Insider·TeamTalk £25m, 07-21 전후)이라 단계·최신성 모두 열위다. 어제 대등 판정의 근거였던 **뉴캐슬은 조용해졌다**. [경쟁구도] 알-힐랄 우위. 반대 방향 캐비앗: **선수 본인이 PL 선호를 명시**했고("언젠가 PL에서 뛰는 게 꿈"), 갈라타사라이는 €35m 미만 검토 불가라 알-힐랄 €30m도 최소가 미달이다. 따라서 즉시 DEAD가 아니라 MEDIUM으로 두고, **알-힐랄 공식 오퍼가 실제 제출되는지**를 다음 실행에서 확인한다. [2026-08-01] 07-31 MEDIUM 강등이 행에 반영되지 않아 지금 숨김 처리한다(2026-07-30 결정: 등급 강등도 삭제가 아니라 DEAD 숨김 — map25·fit_sim 보존). 오늘 확인: 알-힐랄 ~€30m(보너스 포함) 오퍼가 "수일 내 제출" 단계에서 **아직 미제출**, 갈라타사라이는 €35m 미만 불검토 재확인 → 격차는 벌어지지 않았으나 빌라는 여전히 대리인 접촉뿐이라 복원 근거 없음.'),'Football Insider(2티어) "hopeful of winning race" ; TeamTalk(2티어) £25.5m 오퍼 보도 ; CaughtOffside(2티어) ; SofaScore API player 913593 (2026-07-21); TeamTalk; GiveMeSport; TheHardTackle; Yahoo Sports','MEDIUM-HIGH 유지 — 접촉 단계 확인되나 빌라의 우선순위가 낮아져 진전 속도는 느림.','사라','2026-07-30');
INSERT INTO transfer_targets VALUES(127,'AVL','2026-summer','Rafael Leão',NULL,NULL,'AC Milan','LW','LM','DEAD (빌라 사실상 철수 — Moretto가 진짜 후보를 터키 2팀으로 한정)','245108X610434302101000100',34.10000000000000142,65.70000000000000284,6,7.030000000000000248,'wm_wideplm','Attack','wm_wideplm','Attack',0.7800000000000000266,'로저스 대체 좌측 윙 후보, 이적 요청서 제출한 상태. [2026-07-27 21시 최신화] La Gazzetta dello Sport: 레앙이 밀란에 공식 이적 요청서 제출, 빌라를 PL 측 최우선 구단으로 지목. 호가는 초기 £50m/€60m에서 €50m 선으로 하락 조짐. 단 Tuttosport는 "에스투피냔 협상 중 나온 탐색성 문의" 수준이라 명시 — 클럽 간 공식 협상 개시는 아직. [2026-07-28 FC26 통합 확인] 실측 wideplm/Attack 0.780 vs insidefwd 0.719 — Δ0.061 유의미, 데이터 우선 유지. 캐비앗: FC26 숙련은 w_insidefwd++(레벨2)·wm_insidefwd+ — 게임 내 숙련 마커는 insidefwd에만 있음. PAC93/#속도광/#드리블러는 양쪽 다 지지. [2026-07-29 14시 재확인 — 유지] 이적요청서 효과로 호가 연화(€60m→€50m, £38m선 가능 보도). 빌라=주요 PL 수터(Gazzetta)이나 공식 오퍼 미제출. 상충 신호: football-italia "선수 마음은 아스날". 멘데스가 행선지 키 보유. [경쟁구도 2026-07-30] 경쟁 우위 — 페네르바흐체가 협상 단계(7/28 이사 밀라노 방문, €40m+애드온·연봉 €8m 제시), 갈라타사라이도 협상 단계(중개인, 연봉 €10m net). Moretto(1티어) 직접 인용: "레앙을 원했고 지금도 원하는 진짜 클럽은 갈라타사라이와 페네르바흐체 둘뿐". Longo(2티어): 빌라·토트넘은 제안을 받아 조건만 파악하고 현재 다른 타깃 검토 중. 토트넘은 철수 확정. 밀란 호가 €60m(Gazzetta는 €40–50m면 성립), 최종 결정 8월 이월 → 8월 호가 하락 시 재점화 여지 있어 삭제 대신 숨김.','La Gazzetta dello Sport(2티어급 이탈리아 매체) ; Sports Mole(2티어) "surprise move" ; Get Italian Football News ; SofaScore API player 851284 (2026-07-21) ; Gazzetta via yahoo fenerbahce-submit-bid ; sempremilan aston-villa-leao-approach (재검증 07-26); La Gazzetta dello Sport; Tuttosport(경유); Sports Mole; TheHardTackle; SportMediaset(경유)','MEDIUM-HIGH 유지 — 선수의 공식 이적 요청과 빌라 우선순위 지목은 확인되나, 구단 간 공식 협상은 탐색 단계. / [2026-07-30] DEAD 숨김(8월 재점화 여지, 복원 시 등급 재판정).','레앙','2026-07-28');
INSERT INTO transfer_targets VALUES(129,'AVL','2026-summer','Alejandro Garnacho',NULL,NULL,'Chelsea','LW','LM','CONFIRMED','88210X4101720004100011000',22.30000000000000071,66.5,6,7.030000000000000248,'wm_winger','Attack','wm_winger','Attack',0.8040000000000000479,unistr('첼시 초기 로그론 + 의무구매옵션(사실상 확정), 4년 계약. Romano "here we go" + Ornstein 메디컬 완료 확인 (2026-07-22/23). [2026-07-28 FC26 통합 확인] 실측 0.911 + 숙련 wm_insidefwd+ 일치 + PAC86/감아차기 — 처방 확정.\u000a\u000a[2026-07-31 obs#94 커널 교체 + H안 재설계] 처방을 wm_insidefwd/Attack → **wm_winger/Attack .804**(숙련✓)로 교체. 옛 placedMap이 인사이드 포워드 커널을 터치라인(x=14)으로 시프트해 적합을 .911로 부풀리고 있었고, EA 정본 변형으로는 .671이다. 실측에 맞는 것은 winger 계열이며 좌측 해방의 성격이 컷인 → 터치라인 침투로 바뀐다. 뱅크는 0.00 유지라 C1(두 줄 4) 무사.'),'https://sports.yahoo.com/articles/aston-villa-agree-deal-sign-170000479.html','HIGH — 1티어(Romano exclusive, Ornstein medical) 확인','가르나초',NULL);
INSERT INTO transfer_targets VALUES(130,'AVL','2026-summer','Martin Baturina','마르틴 바투리나',1090019,'Como','AM','CAM','DEAD (STALE — 최신 보도 2026-07-20 이후 2주+ 무소식)','532128X651552113421101000',37.20000000000000285,61.5,6,7.120000000000000106,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.7109999999999999654,unistr('틸레만스(→Man Utd)·로저스(→Chelsea) 유출 공백을 메울 창조형 미드필더 후보. 월드컵 잉글랜드전 골로 주가 상승, Como는 "매각 불가" 방침이었으나 최근 태도 완화 보도. 25/26 34경기 8골 4도움. [2026-07-27 21시 최신화] 빌라의 공식 오퍼(€50-55m)가 코모에 거절됨 확인(Football365/Football365 경유 코모 회장 발언) — 코모는 €80m 고수, 바이에른도 새로 경쟁 합류. 오퍼 제출까지는 갔으나 거절되어 HIGH 승격 요건(합의 단계) 미충족. [2026-07-28 FC26 통합 확인] 실측 argmax 0.711(2위 classic10/Versatile 0.691) 유지 — 데이터 우선. 캐비앗: FC26 숙련 cam_playmaker+·예리한패스/인벤티브/퍼스트터치 PS는 플레이메이커 성향 — 게임 내 숙련 마커를 원하면 cam_playmaker/Roaming(0.676) 대안. [2026-07-29 14시 재확인 — 유지] 빌라 공식 제안 €50-55m(£43-48m) 제출 → Como 거절(Gazzetta via SW), €80m 요구·2030 계약이라 매각 불요 입장. 경쟁: 맨유·토트넘·바이에른. 로저스 매각 재원으로 증액 여지. [경쟁구도 2026-07-30] 빌라 우위(근소) — 공식 입찰(€50–55m, 6/8)을 낸 유일한 클럽. 토트넘은 회담만(7/7, 입찰 없음), 맨유·바이에른은 관심·문의 단계. 다만 빌라 입찰이 가장 오래돼 최신성은 열위. 양방향 캐비앗: 코모 회장 "거절을 두려워하지 않는다"(7/20), 파브레가스 잔류 희망, 선수 본인 코모 만족·계약 2030, 갭 £48m vs £69m.\u000a\u000a[2026-07-31 경쟁 판정 정정 — 빌라 우위 → 대등] 어제의 "공식 입찰을 낸 유일 클럽" 전제가 **틀렸다**. **토트넘도 2026-06-06 €50m 입찰 이력 + 2026-07-07 대리인 협상**이 확인된다(24 Sata 경유 Sport Witness, 2티어) — 빌라와 동일하게 코모에 거절당한 같은 단계다. 바이에른은 3티어(Ekrem Konur), 맨유는 Sky Italia 링크만. [경쟁구도] 대등(토트넘·바이에른). 구조적 열위: 코모 회장이 €80m 고수·계약 2030·매각 불요를 공개 천명한 반면 **빌라 지출 상한은 £40m**(Tanswell 1티어)이라 갭이 가장 크고, 토트넘은 니코 파스에 €70m까지 올린 지불력이 있다. 등급은 대등 판정의 표준 처리로 **MEDIUM-HIGH 유지**. ⚠️ 최신 보도 07-20으로 11일 경과 — 다음 실행에서 STALE 경계.'),'Sky Sports(Sky Italia 인용, 1티어): Villa 관심 확인, Como 요구 €80m; Athletic Jacob Tanswell(1티어): Villa 지출 상한 £40m 언급 — 재정 제약 캐비앗; Football365(코모 회장); Football Fancast; GiveMeSport; Yahoo Sports; CaughtOffside; SofaScore API /player/1090019 events+heatmap+statistics (2026-07-28 수집)','MEDIUM-HIGH 유지 — 공식 오퍼 제출·거절까지 진행되었으나 밸류에이션 격차가 커 HIGH 미달. / 2026-07-28 실측 완료: 클럽 6경기(세리에A 5·코파 1, 전부 45분+, 히트포인트 47~76) 포지션-순수 표본 — 월드컵·친선 6경기는 대표팀 맥락이라 제외. 코파(Inter전)는 라인업 표기 F이나 중심좌표가 세리에A CAM과 일치해 포함. 커널 적합 cam_halfwinger/Balanced 0.711(HIGH), 제노아 원정 1경기만 저지대 아웃라이어.','바투리나','2026-07-20');
INSERT INTO transfer_targets VALUES(133,'AVL','2026-summer','Harvey Barnes','하비 반스',NULL,'Newcastle United','LW','LM','DEAD (뉴캐슬 재계약 공식 발표 2026-07-27 — 매물 소멸)','44221X4111521011100101100',29.89999999999999858,65.40000000000000569,235,6.599999999999999645,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.6460000000000000186,'빌라 좌측 와이드 보강 후보. 뉴캐슬과 2028년까지 계약 중이나 £38m 원 이적료 기준 협상 여지. 선수 본인이 미들랜즈 복귀(가족 근접) 희망한다는 전 CEO(Keith Wyness) 발언 다수, 25/26시즌 16골 활약 근거. [2026-07-27 21시 최신화] Keith Wyness(전 빌라 CEO, Football Insider 경유) — 선수 측 미들랜드 복귀 희망 확인. 뉴캐슬(하우 감독)은 잔류 희망하며 저항 중, £40m 밸류에이션. 램지-반스 스와프딜 가능성도 거론. [2026-07-28 FC26 통합 재판정] 현행 커널 재검산 argmax wm_insidefwd/Balanced 0.929(2위 동역할 Attack 0.843) — 기존 widemid/Build-Up 0.813은 구스캔 잔재로 교정. FC26 숙련 wm_insidefwd+·감아차기 PS·SHO81 3축 모두 일치. [2026-07-29 14시 재확인 — 유지] 뉴캐슬이 고든 바르사행(£70m 합의) 후 잔류 방침 경화 — 하우가 고든 대체 주전으로 검토, 블록 예정 보도(Football Insider). 선수 의사(미들랜즈 복귀)는 유효, ~£40m이면 매각 여지. [경쟁구도 2026-07-30] 판정 불필요 — 뉴캐슬이 7/27 구단 공식 발표로 장기계약 연장(1티어 최상위 근거, 반박 여지 없음). 하우 감독·SD 윌슨이 "장기 플랜의 일부"로 코멘트, 고든(→바르사)·토날리(→토트넘) 이탈 후 반스가 제1 좌측 윙어. 빌라 링크는 5~6월 관심 단계(2~3티어)에서 종료.','Football Insider247(2티어, 복수 기사: "closely watching"/"boost") ; TeamTalk(2티어) ; CaughtOffside(2티어) ; Keith Wyness(전 빌라 CEO) 발언(givemesport); Football Insider(Keith Wyness); TeamTalk; CaughtOffside; FootballTransferTavern','MEDIUM-HIGH 유지 — 선수 이적 희망 확인되나 뉴캐슬의 매각 저항으로 진전은 더딤. / [2026-07-30 DEAD] 근거=newcastleunited.com 공식. last_news_date는 빌라 링크 기준 날짜를 특정할 수 없어 NULL 유지.','반스',NULL);
INSERT INTO transfer_targets VALUES(134,'AVL','2026-summer','Lucas Bergvall','루카스 베리발',1391251,'Tottenham Hotspur','M','RDM','DEAD (강등 MEDIUM — 실입찰 3클럽 대비 빌라 미입찰, 최신 경합 명단 이탈)','211230127X11273116X600100',67.29999999999999716,52.0,6,6.299999999999999823,'dm_dlp','Roaming','dm_dlp','Roaming',0.6570000000000000284,'[2026-07-27 신규] 틸레만스(맨유행 확정 유출) 대체 후보로 부상. Yahoo Sports "Sources: 빌라 재점화, 오픈 레이스"(Athletic 계열=1티어) + Football Insider·TeamTalk(2티어) 관심 보도, 이적료 ~£50m, 계약 2031. 경쟁 첼시·노팅엄 포레스트. ★댐퍼: Sky Michael Bridge — 스퍼스 "이번 여름 매각 불가" 입장 통보. 실측 THFC 최근 45+ 6경기(192pt, 시즌말 출전 급감=이적추진 정황): 중심 tool(67,52) 우중앙. RDM 커널 fit dm_dlp/Roaming 0.806(2위 boxcrasher/Balanced .77). LDM .43·CAM .50 부적합 → RDM 단일 등재(CM b2b .85지만 4-2-3-1에 CM 슬롯 없음). [2026-07-27 21시 최신화] Football Insider(2티어): 노팅엄 포레스트와 함께 선두 경쟁. 단 Sky Sports Michael Bridge(1티어)는 "이번 여름 이적 없다고 스퍼스가 선수에게 통보"라고 반박 보도 — 상충 유지. 선수 본인은 이적 희망 의사 재확인. [2026-07-28 FC26 통합 판정] opt 확정: 실측 argmax dm_dlp/Roaming 0.806(2위 boxcrasher/Balanced 0.772) + 압박검증 PS(전진 압박 아래 배급). 캐비앗: FC26 숙련 cm_b2b+·cam_playmaker+ — DM 계열 숙련 없음. [2026-07-29 14시 재확인 — 유지] 부정 신호: Sky Bridge — 스퍼스가 선수에게 잔류 통보, 클럽간 직접 접촉 없음(£57m 요구 가능). 선수는 이탈 희망 유지. 스퍼스 입장 연화 여부가 관건. [경쟁구도 2026-07-30] 경쟁 우위 — 포레스트 £38m·뉴캐슬 £46m 공식 입찰(모두 거절), 브라이턴은 £60m 호가 충족 의사. 빌라는 입찰 이력 0이고 7/29 Romano 인용 4파전 보도에서 명단 밖. 선수는 정기 출전을 이유로 이탈 강력 희망(Romano), 토트넘은 비매→£50–60m 호가로 전환. £60m은 빌라 PSR 여력과 충돌.','TransferFeed https://www.transferfeed.com/clubs/aston-villa/15 ; Yahoo Sports "Sources: Aston Villa to reignite Lucas Bergvall pursuit amid open race" ; footballinsider247.com ; SofaScore player/1391251 (6 THFC 45+ 2025-12~2026-04); Football Insider; TeamTalk; TheHardTackle; Sky Sports(Michael Bridge, 반박); DeadlineDayLive','MEDIUM-HIGH 유지 — 2티어 경쟁 보도 vs 1티어(Sky) 잔류 통보 반박이 상충, 등급 변동 없음. / [2026-07-30] MEDIUM 강등, DEAD 숨김.','베리발','2026-07-16');
INSERT INTO transfer_targets VALUES(135,'AVL','2026-summer','Emerson Royal','에메르송 호이알',856123,'Flamengo','RB','RB','MEDIUM-HIGH','000250002X000150002600012',86.20000000000000284,56.70000000000000284,6,6.879999999999999894,'fb_att_wb','Support','fb_att_wb','Support',0.949999999999999956,'Matty Cash 백업 필요(안드레스 가르시아 게타페 임대行) — Villa가 Flamengo에 €9m 공식 제안 제출(6/23), Flamengo 거부 후에도 재제안 검토 중. Sky Sports Paper Talk(출처: The Athletic)가 협상 사실 보도, 선수 본인도 공개적으로 제안 수령 확인. 아직 합의 단계 아님(Flamengo 계약 2028까지, 판매 거부 기조) → MEDIUM-HIGH(1티어 협상 보도, 합의 전). [2026-07-29 14시 재확인 — 유지] 디테일 진전: 블록 주체=자르딤 감독(ESPN Brazil Andrade — "회장단은 승인 의향, 감독이 중단"). €9m→€10m 증액 제안도 보류됨. 선수는 공개적으로 긍정 반응, 협상 재개 여지 유효. [2026-07-30 실측 완료] 툴중심(86.2,56.7)=우측 전용. RB 커널 적합 fb_att_wb/Support 0.950 > fb_inverted/Attack 0.923 — 캐시 실측의 동일역할 적합(0.898)을 상회. 전방2행/자기진영2행 질량비 0.53/0.31 vs 캐시 0.33/0.47 → 캐시보다 뚜렷한 전진형 풀백(공격 관여 +0.20, 수비 커버 -0.16). 함의: C(우측 침투) 프리셋의 RB 처방 fb_att_wb/Support에 캐시보다 정합적이나, 자기진영 질량 하락이 이미 라인 48로 내린 C의 수비 리스크를 더한다 — 프리셋 채택은 별도 판단. [경쟁구도 2026-07-30] 빌라 단독 우위(경쟁 클럽 0건) — 오퍼를 낸 유일한 클럽이고 선수도 공개 호응("이 제안을 받아 매우 기쁘다"). 장애물은 경쟁이 아니라 플라멩구의 스쿼드 판단: Casagrande(플라멩구 전담) — 지금 팔면 자르딤이 바렐라의 즉시 대체자를 잃는다는 이유이며 금전 문제가 아니다(빌라는 이미 호가 충족, 결렬이 아니라 냉각). 상향 트리거 = 플라멩구의 우측 백업 확보(에스투피냔-밀란 블록과 동일 패턴).','Sky Sports(via The Athletic) 2026-07; Yahoo Sports/Sports Mole 2026-07','실측 6경기(45분+·히트포인트 62~107): FLA-SPA 90''7.1 / CHA-FLA 90''6.7 / FLA-COR 90''7.1 / FLA-CUS 90''7.1(리베르타도레스) / FLA-ELP 90''6.7(리베르타도레스) / VIT-FLA 90''6.6(코파) — 2026-05-15~07-26, 평균 6.88. 캐비앗: ① 브라질 리그·남미 대회 표본(리그 강도 보정 없음, 시세 LASK 사례와 동일 한계) ② 프리시즌 친선 4경기는 표본 제외 ③ INT-FLA(26'')·CAP-FLA(8'')·GRE-FLA(25'')은 45분 미달로 제외. 측정: claude-in-chrome, SofaScore API event/{eid}/player/{pid}/heatmap.','에메르송','2026-07-28');
INSERT INTO transfer_targets VALUES(138,'AVL','2026-summer','Jonathan Rowe','조나단 로우',1065261,'Bologna','LW','LM','DEAD (강등 MEDIUM — 5파전 최하 단계, 에버턴만 구체 협상)','47210X4412532113221000000',30.5,65.09999999999999431,6,6.830000000000000071,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.7029999999999999583,'[2026-07-30 실측으로 슬롯 정정 — 원래 RM 행이었으나 삭제] 루머 등급은 유지(Tanswell 1티어: 유력 타깃, 이적 파라미터 공식 논의). 그러나 실측은 우측이 아니다: 툴중심(30.5,65.1)=좌측 편향, RM(x=86) 커널 최고 적합 0.155로 §3-4 부적합 기준(<0.4) 미달 → RM 행 성립 불가. LM(x=14)에서 wm_insidefwd/Balanced 0.832(Attack 변형 0.797 근접) = 좌측 인사이드 포워드. 침투 서명 전방0.64/자기진영0.15는 브리프 요구(하지무사 0.76/0.14, 디아비 0.62/0.18)를 좌측에서 충족하나, 디아비 우측 템플릿 코사인은 0.534로 낮고 산초 실측(좌측형)과 0.833 — 즉 obs#38 "우측 윙어" 착지점이 아니라 가르나초(CONFIRMED LM)·반스·레앙과 경합하는 좌측 옵션이다. 불변규칙 #3(실측>서사) 적용 사례. [경쟁구도 2026-07-30] 경쟁 우위 — 빌라는 문의(enquiry) 단계에 머물고 에버턴만 조건 협상(firm discussions, 7/22–27)으로 한 단계 앞섬. 첼시·맨유·뉴캐슬도 동일 문의 라인. 선수 선호 정보 0건. 볼로냐 호가 €40–45m·계약 2029·매각 의지 낮음. 오늘 실측이 그를 LM으로 재분류했고 그 슬롯은 가르나초(CONFIRMED)로 채워져 빌라 측 동기 자체가 약하다.','Jacob Tanswell/The Athletic (via readastonvilla 2026-06-02); 실측: SofaScore API(claude-in-chrome) 2026-07-30','실측 6경기(45분+·히트포인트 32~61): BOL-INT 90''7.3 / ATA-BOL 88''6.8 / BOL-CAG 45''7.3 / BOL-ASR 90''6.6 / AVL-BOL 90''6.0(UEL — 빌라 상대 경기) / CRE-BOL 78''7.0 — 2026-04-05~05-23, 평균 6.83. 캐비앗: ① 표본이 4~5월로 2026-07 프리시즌 친선 3경기는 제외(친선 데이터 신뢰 낮음) ② 히트포인트 32~61로 후보군 중 저관여 표본 ③ NAP-BOL(17'')·JUV-BOL(31'')·BOL-LEC(16'')은 45분 미달 제외 ④ 서사(우측 타깃)와 실측(좌측) 충돌 자체가 기록 대상. / [2026-07-30] MEDIUM 강등이나 DEAD 숨김(오늘 측정한 실측 .832 보존).','로우','2026-07-22');
INSERT INTO transfer_targets VALUES(139,'AVL','2026-summer','Allan','아우안',1835889,'Palmeiras','RW/CAM','RM','MEDIUM-HIGH','001361125X001360013500001',77.20000000000000284,59.39999999999999858,6,7.179999999999999716,'wm_winger','Balanced','wm_winger','Balanced',0.8120000000000000551,'로저스(첼시 £117m) 대체 창조 자원. 빌라가 €25m+옵션 €5m(총 €30m)·5년(+1년 옵션) 공식 입찰 → 팔메이라스 거절. SD Anderson Barros가 대리인에게 "협상 의사 없음" 직접 통보, 요구선 €45m 초과(나폴리 €35m·뉴캐슬·제니트 기거절). 계약 2029로 셀링클럽이 협상력 우위. [경쟁구도 2026-08-01] 단계는 빌라가 최선두(유일한 실제 입찰) — 뉴캐슬·리버풀은 관심 단계 보도뿐. 판정 **빌라 우위**이나 병목은 경쟁 클럽이 아니라 **셀링클럽 블록**이다. 등급 유지(HIGH는 협상 단계 요건 미충족 — 상대가 협상 자체를 거부). [실측 2026-08-01] SofaScore 히트맵 6경기(45분+·히트포인트 15+, 2026-05-05~07-30, 전부 팔메이라스) 균등가중 그리드. 중심 툴좌표 (77.2, 59.4) = **우측·전진** 편향이 뚜렷하고 평균 평점 **7.18**(최고 8.4). RM 슬롯(x=85) 커널 적합 **wm_winger/Balanced .812** — 기존 RM 후보 하지무사 .821·은디아예 .825와 **동급**이고 둘 다 DEAD인 지금 RM 슬롯의 유일한 실측 보유 후보다. ⚠️ W군(순수 윙어)으로 재면 w_wideplm/Build-Up .870으로 더 높다 = **뱅크(WM) 역할보다 해방 윙어에 가까운 풋프린트**이며, 에메리 우측이 요구하는 4-4-2 복귀(obs#27)와는 그만큼 어긋난다. CAM으로 재면 .674로 급락 → 등재 슬롯은 RM이 맞다. [2026-08-01 처방] opt=fit=wm_winger/Balanced(.812) — 타 영입 후보와 같은 규약(실측 argmax를 처방으로). ⚠️ 현 구조에서 RM은 두 줄 4의 **뱅크 칸**이라(obs#124) 실제 기용 시 wm_widemid/Support **.734**를 지불하게 된다(−.078). 즉 아우안은 해방 사이드용 자원이고, 좌측이 이미 해방으로 우세한 현 스쿼드에서는 구조적으로 어긋난다. [2026-08-02] ESPN Brasil(Bruno Andrade): 빌라는 **포기하지 않았고 2차 입찰을 준비 중**이다 — 다만 **아직 제출 전**이라 단계 변화는 없다(등급 유지). 팔메이라스가 협상 자체를 거부 중이라 이번 창 내 성사는 회의적이고, 브라질 시즌 종료 후 1월 재평가가 현실적이라는 관측이 병기된다. [2026-08-03] 셀링클럽 구조 제약 확인 — 팔메이라스는 Allan 경제권 70%를 보유하고 **국외 이적 바이아웃 €100m(R$630m)** 이 걸려 있다. ⚠️ 이 조항은 빌라 관심에 대한 신설 대응이 아니라 **2024-11 재계약 때부터 존재하던 상수**다(ESPN Brasil, 최초 보도 2025-02-25 — 당시 2027 만료·€100m, 이후 2029로 연장). 즉 €45m+ 요구선과 €100m 조항은 별개 층이며, 협상 결렬 시 빌라가 넘어야 할 실제 천장은 후자다. 추가로 아벨 페레이라가 기자회견에서 "협상이 이뤄진다면 주변부 선수에 한한다"고 직접 발언(1차 출처=공개 회견). ⚠️ **2030까지 재연장+조항 증액 협상 중**이라는 서술은 thefootball.com.br(3티어, 기자 미표기) 단독이라 채택하지 않는다 — ESPN 기사에는 해당 내용이 없다.','ESPN(1티어, Adriana Garcia 기명, sources 표기, 2026-07-29) https://www.espn.com/soccer/story/_/id/49478318/aston-villa-premier-leauge-allan-brazilian-serie-30-million-offer-rejected-sources ; 최초 정보 André Hernan(BR) ; TEAMtalk','MEDIUM-HIGH — 1티어가 **실제 제출된 입찰**을 확인(단순 관심 아님). 실측 완료(2026-08-01) — 6경기 균등가중, 인코딩 규약은 맥긴 14023928 회귀 검증(44포인트·25셀 완전 일치)으로 확인. ⚠️ 표본이 전부 **브라질 세리에A**라 리그 수준 보정 없음. ⚠️ 적합 .812는 슬롯 유형 WM 제한 하의 argmax이고, 무제한이면 W군이 더 높다(위 캐비앗). [2026-08-03] €100m 바이아웃은 ESPN Brasil로 교차 확인됨(신설 아님·상수). 2030 재연장설은 미채택(3티어 단독).','아우안','2026-08-02');
INSERT INTO transfer_targets VALUES(140,'AVL','2026-summer','Robin Risser','로뱅 리세',1387161,'RC Lens','GK','GK','DEAD (STALE — 최신 보도 2026-07-20 이후 2주+ 무소식)','0000000000000000101002X20',51.70000000000000284,12.19999999999999929,3,7.030000000000000248,'gk_goalkeeper','Defend','gk_goalkeeper','Defend',0.982999999999999985,'마르티네스 유벤투스행(HIGH) 대비 GK 승계 1순위. L''Équipe(Loïc Tanzi): 빌라가 **오프닝 오퍼 준비, 제출 임박**하며 **회장이 직접 관여**, 레스테스(툴루즈)에서 리세로 우선순위 전환. 25/26 리그1 준우승 주전·**UNFP 올해의 GK**·리그1 베스트11·프랑스 WC 3옵션. 21세 이하 유럽 5대리그 유일 10클린시트+75세이브. 장애물: 계약 **2030**(작년 여름 갱신), 랑스 매각 불원, 본인도 "UCL 위해 한 시즌 더" 발언. [경쟁구도 2026-08-01] 벤피카·첼시 관심설은 단계 미상 → 판정 **빌라 우위**, 병목은 셀링클럽 블록. [실측 2026-08-01] 히트맵 3경기(45분+·15포인트+, 2026-05-08~05-22)만 조건 충족 — 표본 얇다. 중심 (51.7, 12.2), 평균 평점 **7.03**. GK 커널 적합 **gk_goalkeeper/Defend .983**로, 현 프리셋의 마르티네스 처방(gk_goalkeeper/Defend .961)과 **역할·포커스가 동일**해 슬롯 교체 시 전술 구조 변경이 필요 없다. ⚠️ GK 그리드는 질량이 골문 앞 2~3칸에 몰려 **어느 GK를 재도 비슷하다** — 이 .983은 판별력이 거의 없는 수치이고 GK 선택의 근거로 쓰면 안 된다(gk_sweeper .825와의 차이도 스위핑 성향이 아니라 표본 얇음의 산물일 수 있다). [2026-08-02 ⚠️전제 소멸] 이 행의 근거는 "마르티네스 유벤투스행 대비 GK 승계"였는데, **오늘 Romano(1티어)로 유베 철수가 확인**됐다(transfer_outgoing 마르티네스 DEAD 참조) → **수요 근거 자체가 사라졌다**. 그럼에도 오늘 등급을 내리지 않는 이유: §2 등급표는 **빌라 링크 보도의 티어**를 재는 축이고 리세 링크의 티어(L''Équipe 1티어)는 변하지 않았다. "빌라가 GK를 안 사도 된다"는 **추론**이지 빌라-리세 링크에 대한 새 보도가 아니므로, 추론으로 등급을 내리면 서사 우선이 된다(불변규칙 3의 역방향 오용). ⏳ 대신 **last_news_date=2026-07-20이 유지되므로 08-04에 STALE로 자동 숨김**된다 — 규칙이 이미 이 건을 처리한다. 오늘 빌라 링크 신규 보도 0건 확인.','L''Équipe/Loïc Tanzi(1티어, 2026-07-04) via getfootballnewsfrance·onefootball·lensois ; Le Parisien(2티어, 2026-07-20) via tellementfoot https://tellementfoot.com/rc-lens-lavenir-de-robin-risser-bouleverse-par-aston-villa-22779/','MEDIUM-HIGH — 1티어(L''Équipe) 관심+오퍼 준비 보도 = §2 요건 충족. ⚠️ **보도일 함정 주의**: 스캔 에이전트가 "7월 말"로 넘긴 오퍼 준비 기사는 실제 **2026-07-04**(28일 전)다. 살아 있는 근거는 Le Parisien 07-20(관심 유지, 단계 진전 없음)이라 last_news_date는 07-20으로 잡았다. 실측 완료(2026-08-01, 3경기) — ⚠️ **적합도를 근거로 쓰지 말 것**: GK 히트맵은 선수 간 변별력이 사실상 없다. map25는 툴 렌더링용으로만 유효하다. ⚠️ 2026-08-02: 수요 전제(마르티네스 이탈) 붕괴 — 이 행은 08-04 STALE 예정이며, 그 전에 새 보도가 없으면 되살릴 근거도 없다.','리세','2026-07-20');
INSERT INTO transfer_targets VALUES(141,'AVL','2026-summer','Matteo Ruggeri','마테오 루헤리',965011,'Atlético Madrid','LB','LB','HIGH','32100X2000410007200031000',13.59999999999999965,47.20000000000000284,6,6.769999999999999574,NULL,NULL,'fb_att_wb','Support',0.948999999999999955,'좌측 풀백 — 아틀레티코가 그리말도(레버쿠젠, ~€20m) 영입 후 방출 대상으로 분류, 시메오네 구상 외. 빌라는 디뉴(→PSG 확정) 공백 + 에스투피냔 딜의 밀란 승인 정체가 겹쳐 즉시 영입 가능한 대안으로 선회 — Marca/Moretto는 ''빌라가 오퍼 제출, 선수가 검토 중, 몇 시간 내 결정 가능''으로 보도. 이적료 €20m 내외(아틀레티코 매입가 €17m+보너스 €3m 대비 차익). 선수 측(대리인 Tullio Tinti)이 아틀레티코 훈련장 방문, 본인은 화요일 훈련 제외. [경쟁구도 2026-08-04] 빌라 우위 — 유벤투스·로마 링크가 병기되지만 Moretto는 두 팀을 ''진짜 관심 아님''으로 선을 그었고 피오렌티나 링크는 2주 전 것이다. 현재 실제 오퍼를 낸 클럽은 빌라뿐 → §2-1 ''빌라 우위·단독''으로 등급 유지(상향은 1티어 협상/합의 보도 시). [실측 2026-08-04] SofaScore 965011, 최근 6경기(45분+·히트포인트 15+ 충족: LaLiga 05-24·05-17·05-12·05-09, UCL 05-05·04-29 — 05-02 발렌시아전은 출전 기록 없어 제외, 프리시즌 친선 2경기도 제외). 경기당 정규화 후 균등가중. fc26-heatmap.html의 roleOptions(''LB'', map25)로 직접 채점(별도 구현 없음, 회귀검증: MAPS 37역할·st_false9 존재·에스투피냔 .946/에메르송 .950 재현 확인). 슬롯 LB(x=13) 기준 fb_att_wb/Support 0.949 — 2위 fb_att_wb/Attack 0.735 대비 Δ.214로 동점 구간 무관 단독 1위. 에스투피냔(.946)과 사실상 동급 프로필이라 대체재로 정확히 기능한다. [2026-08-05 재확인 — 등급 유지] Luca Cerchione(이탈리아 기자) "이미 합의 도달"(€18m+€3m) 보도가 재순환하나 Moretto의 "선수 개인 수락 여부 불투명" 판단과 상충 — 1티어(Romano) 확인 없음. 유벤투스·로마 경쟁 언급도 신규 근거 없이 재순환(기존 Moretto "진짜 관심 아님" 판단 유효). 신규 악화·개선 신호 없음. [2026-08-05 심층 — 등급 MEDIUM-HIGH 유지, 근거 기반 강화] ⑴ 1티어 2축이 독립적으로 확인됨: The Athletic(Jacob Tanswell, 빌라 전담 1티어) "빌라 관심 + 에메리가 원하는 LB physical profile에 부합, 총액 ~€25m" + Marca(Isaac Suárez) via Moretto. 08-04 기록의 "1티어 직접 확인 미발견"은 이로써 해소 — §2표의 MEDIUM-HIGH 요건(1티어 관심 보도)을 정면 충족한다. 단 1티어가 확인한 것은 관심·프로필 적합까지이고 "클럽간 합의"는 Cerchione 단독이라 HIGH(1티어 협상/합의) 미충족. ⑵ 서사가 아닌 물리적 신호 2일 연속: 08-03 선발조 제외(유스 Arnau Sola가 그 자리) + 대리인 Tinti·Montipo가 마드리드 훈련장서 단장 Alemany와 대면 회담, 08-04 실내 자전거로 팀훈련 관전(훈련 미참가). ⑶ 아틀레티코 매도 동기 구조적 검증: 그리말도(2026-06-28 발표)+Hjulmand+Kang-in Lee 지출로 수입 필요, 매입가 €17m 대비 차익 확실, 무엇보다 Hancko가 LB 커버 가능해 대체 영입이 불필요하다 — 팔 이유는 있고 안 팔 이유가 없다. ⑷ 경쟁 실체 없음(Moretto가 유베·로마 직접 부정, 피오렌티나는 7월 이후 진전 없음) → 선수가 기다려도 받을 대안 오퍼가 현재 없다. ⑸ 빌라 측 시간 제약: 디뉴 이탈로 LB가 마첸 1명, 08-12 UEFA 슈퍼컵 상대가 PSG. 에스투피냔 플랜A는 아모림에 막혀 실질 폐쇄. ⑹ 잔여 리스크: 선수 수락·개인조건 합의가 어떤 소스에도 없고("la llave la tiene el jugador"), 메디컬 기록 전무, Romano/Ornstein/Sky UK/BBC 부재. [실측 재검증 2026-08-05] roleOptions(LB,x=13) 재실행 — fb_att_wb/Support .949 재현, 2위 fb_att_wb/Attack .735로 Δ.214. LB 후보 4인 중 최대 마진(에스투피냔 Δ.178 / 디뉴 Δ.044 / 마첸 Δ.026=동점구간). 대역분해: 공격3rd 17%·공격미들 33%(피크)·미들 14%·수비미들 25%·수비3rd 11%. 상호 코사인 — 에스투피냔 .975(사실상 동일 프로필, 완전 등가 대체재) / 디뉴 .909 / 마첸 .929(기존 자원과 역할 미중복). [서사 vs 실측 충돌 판정 2026-08-05 — 불변규칙 3] Total Football Analysis 스카우트 리포트는 루헤리 시그니처를 "언더랩(상대 풀백-CB 사이 침투)"·"공격 지표 전반 평균 이하"로 규정하나, 이 리포트는 2025-07-24 발행분이고 데이터가 아탈란타 24/25(가스페리니 3-4-3 LWB) 기반이다. 아틀레티코 25/26 실측은 반대다 — 터치라인 열 75%/하프스페이스 22%/중앙 3%로 폭을 제공하는 오버랩형이며, 디뉴(col0 76%)와 사실상 동일한 너비 규율이고 안으로 접히는 마첸(col0 64%·col1 28%)과 명확히 구분된다. Marca의 25/26 서술("carreras de superposicion이 그의 인장")이 실측과 일치. → 에메리 모듈레이션 4축의 "디뉴 vs 마첸" 축에서 루헤리는 디뉴 자리(전진·폭 제공)에 들어가며, 마첸과 역할이 겹치지 않는다. 다만 디뉴가 공격3rd 22%까지 밀고 올라가는 최종선 유형이라면 루헤리는 공격미들 대역 중심이라 fb_att_wb/Support 커널(col0 3/10/6/6/3)에 디뉴(.886)보다 더 잘 맞는다. [2026-08-06 상향 MEDIUM-HIGH→HIGH] 구단 간 합의 도달 — Marca(2티어): 고정 €18m + 보너스 €6m(총 €24m), Rubén Uria(2티어 스페인): 총액 €25m 원칙 합의. Moretto(2티어 이탈리아): 남은 관문은 선수의 "definitive yes" 하나 — 개인조건·메디컬 미완. 루제리는 아틀레티코 한국 프리시즌 투어 명단에서 제외돼 이적을 검토 중. [경쟁구도] 리버풀·뉴캐슬·유벤투스·로마가 관심을 보였으나 구단 합의에 도달한 곳은 빌라뿐 — 빌라 우위. The Athletic(1티어)은 빌라의 좌풀백 후보군에 루제리를 포함해 보도(관심 단계). [2026-08-07 09시 재확인 — HIGH 유지, **1티어 근거 최초 확보**] "definitive yes"는 오늘까지 미발행이라 CONFIRMED 승격 불가. 그러나 실질 진전이 있다: **Jacob Tanswell(The Athletic 빌라 전담, 1티어)**이 1874 Podcast에서 **"이적료는 대체로 합의됐고 현재 개인조건을 마무리 중"**이라고 확인했다. 08-06까지 이 건의 근거는 Marca·Uria·Moretto(전부 2티어)뿐이었으므로 **처음으로 1티어가 붙은 것**이 오늘의 변화다(HIGH 등급의 근거 기반이 사후적으로 보강됨). ⚠️ **팟캐스트 발언 시점 확정 실패** → §2-0에 따라 `last_news_date` 갱신 근거로는 쓰지 않고 rationale에만 남긴다. 선수 성향에 대해 "빌라 제안 수락 쪽으로 기울었다"는 2티어 전언이 있으나 08-04 Marca의 "타 구단 제안을 기다릴지 저울질"과 톤이 반대라 확정 근거로 쓰지 않는다.','Marca(스페인 전국지, 원출처) via Matteo Moretto(준1티어) ; https://www.sportsmole.co.uk/football/aston-villa/transfer-talk/news/emery-wants-to-sign-italian-defender-immediately-as-aston-villa-bid-to-resolve-clear-issue_602381.html ; http://insidefutbol.com/2026/08/04/aston-villa-push-for-defender-as-he-weighs-his-options/722198/ ; https://www.eurosport.es/futbol/mercado-de-fichajes-2026/2026/aston-villa-interes-matteo-ruggeri-atletico-de-madrid_sto23325237/story.shtml ; https://uk.sports.yahoo.com/news/aston-villa-could-seal-immediate-101500950.html ; SofaScore /api/v1/player/965011/events/last/0 + /event/{eid}/player/965011/heatmap|statistics ; The Athletic(Jacob Tanswell, 1티어, 2026-08-04, paywall 미열람 — 인용 3매체 발행시각 일치로 확정) ; Marca(Isaac Suarez) 2026-08-04 via Sport Witness ; https://www.givemesport.com/aston-villa-identify-mattero-ruggeri-digne-replacement-transfer/ (2026-08-04) ; Tinti 발언 https://www.romaforever.it/2026/07/21/ruggeri-si-allontana-lagente-tinti-fa-chiarezza-sul-suo-futuro/ (2026-07-21) ; Total Football Analysis 스카우트리포트 2025-07-24(⚠️아탈란타 24/25 데이터) | https://www.marca.com (2026-08-05, via readastonvilla.com/2026/08/05/aston-villa-agree-20m-matteo-ruggeri-deal-as-final-hurdle-remains/) | https://insidefutbol.com/2026/08/05/aston-villa-move-blocked-for-now-as-definitive-yes-is-missing/ (Moretto)','MEDIUM-HIGH — 2티어(Marca, 원출처 직접 보도) + 준1티어(Moretto)가 오퍼 제출 단계를 보도. 1티어(Romano/Sky/BBC/Athletic) 직접 확인은 검색에서 미발견이라 HIGH 미충족. §2-0 발행일 검증 통과: 발행일 2026-08-04 확정, 나이 표기 24세가 실제(2002-07-11생 → 24세)와 일치, 병기 정황(그리말도 아틀레티코 입단·그리스만 올랜도 자유이적·랑글레 벤피카 임대·디뉴 PSG)도 현재 상태와 부합 → 1년 오차 함정 아님. 캐비앗: ⑴ 선수 결정 대기 상태로 무산 가능성 상존, ⑵ 2주 전 대리인 Tinti의 ''아틀레티코 잔류가 계획'' 발언(Sky Sport Italia)과 상충 — 오늘 보도가 더 최신이라 채택하되 상충 사실 명기, ⑶ 실측 표본이 25/26 시즌 종료분이라 아틀레티코 1년차 역할 기준(그리말도 영입 전). [2026-08-05 심층 추가 캐비앗] ⑷ 이적료 보도 충돌 — Cerchione €18m+€3m(최대 €21m, 구조 제시) vs The Athletic ~€25m(총액, 티어 우위). 어느 쪽도 다른 1티어가 복제하지 않았다. ⑸ 선수 측 의사 충돌 — 대리인 Tinti의 2026-07-21 Sky Sport Italia 발언 "아틀레티코에 남는다, 시장에 나와 있지 않다"가 08-03~04 훈련 제외·대리인 마드리드 방